import { useCallback, useEffect, useRef, useState } from 'react';
import confetti from 'canvas-confetti';
import { Game } from './game/engine';
import { loadRecords } from './game/levels';
import type { DiffId, HudData, MsgKind, Summary } from './game/levels';
import Hud from './components/Hud';
import type { Msg } from './components/Hud';
import { GameOverScreen, Menu, PauseScreen } from './components/Screens';

type Screen = 'menu' | 'play' | 'paused' | 'over';
const PREFS_KEY = 'bombero-aereo-prefs';

function loadPrefs(): { diff: DiffId; muted: boolean } {
  try {
    const p = JSON.parse(localStorage.getItem(PREFS_KEY) || '{}');
    return { diff: p.diff === 'facil' || p.diff === 'experto' ? p.diff : 'normal', muted: !!p.muted };
  } catch { return { diff: 'normal', muted: false }; }
}

export default function App() {
  const wrapRef = useRef<HTMLDivElement>(null);
  const gameRef = useRef<Game | null>(null);
  const timers = useRef<number[]>([]);
  const msgId = useRef(0);
  const [prefs] = useState(loadPrefs);
  const [screen, setScreen] = useState<Screen>('menu');
  const [hud, setHud] = useState<HudData | null>(null);
  const [msgs, setMsgs] = useState<Msg[]>([]);
  const [summary, setSummary] = useState<Summary | null>(null);
  const [diff, setDiff] = useState<DiffId>(prefs.diff);
  const [muted, setMuted] = useState(prefs.muted);
  const [records, setRecords] = useState(loadRecords);
  const [touch] = useState(() => typeof window !== 'undefined' && ('ontouchstart' in window || navigator.maxTouchPoints > 0));

  const pushMsg = useCallback((text: string, kind: MsgKind) => {
    const id = ++msgId.current;
    setMsgs(m => [...m.slice(-4), { id, text, kind }]);
    timers.current.push(window.setTimeout(() => setMsgs(m => m.filter(x => x.id !== id)), kind === 'big' ? 3200 : 2300));
  }, []);

  const togglePause = useCallback(() => {
    const g = gameRef.current; if (!g) return;
    if (g.mode === 'play') { g.pause(); setScreen('paused'); }
    else if (g.mode === 'paused') { g.resume(); setScreen('play'); }
  }, []);

  useEffect(() => {
    if (!wrapRef.current) return;
    const g = new Game(wrapRef.current, {
      onHud: setHud,
      onMessage: pushMsg,
      onGameOver: s => {
        setSummary(s); setScreen('over'); setRecords(loadRecords());
        if (s.newRecord) confetti({ particleCount: 150, spread: 85, origin: { y: 0.35 }, colors: ['#f59e0b', '#ef4444', '#38bdf8', '#ffffff'] });
      },
    });
    g.input.onPause = togglePause;
    g.input.onAnyKey = () => g.sfx.unlock();
    gameRef.current = g;
    return () => {
      timers.current.forEach(t => clearTimeout(t)); timers.current = [];
      g.dispose(); gameRef.current = null;
    };
  }, [pushMsg, togglePause]);

  useEffect(() => { gameRef.current?.setMuted(muted); }, [muted]);
  useEffect(() => {
    try { localStorage.setItem(PREFS_KEY, JSON.stringify({ diff, muted })); } catch { /* sin almacenamiento */ }
  }, [diff, muted]);

  const setMinimap = useCallback((c: HTMLCanvasElement | null) => { gameRef.current?.setMinimap(c); }, []);

  const play = () => {
    const g = gameRef.current; if (!g) return;
    setMsgs([]); setHud(null); setSummary(null);
    g.setMuted(muted);
    g.start(diff);
    setScreen('play');
  };
  const toMenu = () => { gameRef.current?.toMenu(); setHud(null); setMsgs([]); setScreen('menu'); setRecords(loadRecords()); };

  return (
    <div className="relative w-full h-screen overflow-hidden bg-[#1a0c08] select-none" style={{ minHeight: 320 }}>
      <div ref={wrapRef} className="absolute inset-0" onPointerDown={() => gameRef.current?.sfx.unlock()} />
      {(screen === 'play' || screen === 'paused') && (
        <Hud hud={hud} msgs={msgs} muted={muted} touch={touch} input={gameRef.current?.input ?? null}
          onMute={() => setMuted(m => !m)} onPause={togglePause} onMinimap={setMinimap} />
      )}
      {screen === 'menu' && (
        <Menu diff={diff} setDiff={setDiff} records={records} muted={muted} onMute={() => setMuted(m => !m)} onPlay={play} />
      )}
      {screen === 'paused' && <PauseScreen onResume={togglePause} onRestart={play} onMenu={toMenu} />}
      {screen === 'over' && summary && <GameOverScreen s={summary} onRetry={play} onMenu={toMenu} />}
    </div>
  );
}

import { useEffect, useRef, useState } from 'react';
import type { PointerEvent as RPointerEvent, ReactNode } from 'react';
import { Droplets, Flame, Gauge, Navigation, Pause, Plane, Trees, Volume2, VolumeX, Wrench, Zap } from 'lucide-react';
import clsx from 'clsx';
import type { HudData, MsgKind } from '../game/levels';
import type { Input } from '../game/input';

export interface Msg { id: number; text: string; kind: MsgKind }
interface Props {
  hud: HudData | null; msgs: Msg[]; muted: boolean; touch: boolean; input: Input | null;
  onMute: () => void; onPause: () => void; onMinimap: (c: HTMLCanvasElement | null) => void;
}

const MSG_CLS: Record<MsgKind, string> = {
  big: 'text-3xl sm:text-5xl font-black italic tracking-tight text-amber-200 drop-shadow-[0_4px_18px_rgba(255,110,30,0.7)]',
  good: 'text-base sm:text-lg font-bold text-sky-200 drop-shadow-[0_2px_8px_rgba(0,0,0,0.8)]',
  warn: 'text-base sm:text-lg font-bold text-red-300 drop-shadow-[0_2px_8px_rgba(0,0,0,0.8)]',
  info: 'text-sm sm:text-base font-semibold text-white/85 drop-shadow-[0_2px_8px_rgba(0,0,0,0.8)]',
};
const CARD = 'rounded-xl bg-black/40 backdrop-blur-sm ring-1 ring-white/10';

function Bar({ value, color, icon, label, pulse }: { value: number; color: string; icon: ReactNode; label: string; pulse?: boolean }) {
  return (
    <div className="flex items-center gap-2">
      <div className="w-5 text-white/80">{icon}</div>
      <div className="flex-1">
        <div className="flex justify-between text-[10px] font-mono tracking-widest text-white/60"><span>{label}</span><span>{Math.round(value)}%</span></div>
        <div className="h-2 rounded-full bg-black/50 ring-1 ring-white/10 overflow-hidden">
          <div className={clsx('h-full rounded-full', pulse && 'animate-pulse')} style={{ width: `${Math.max(0, Math.min(100, value))}%`, background: color }} />
        </div>
      </div>
    </div>
  );
}

/** Joystick virtual (virar/subir) y botones de soltar agua y turbo. */
function TouchControls({ input }: { input: Input }) {
  const baseRef = useRef<HTMLDivElement>(null);
  const pid = useRef<number | null>(null);
  const [knob, setKnob] = useState({ x: 0, y: 0 });
  const [held, setHeld] = useState({ drop: false, boost: false });
  const move = (e: RPointerEvent) => {
    const b = baseRef.current; if (!b) return;
    const r = b.getBoundingClientRect(), R = r.width / 2;
    let dx = e.clientX - (r.left + R), dy = e.clientY - (r.top + R);
    const d = Math.hypot(dx, dy);
    if (d > R) { dx *= R / d; dy *= R / d; }
    setKnob({ x: dx, y: dy }); input.touch.turn = dx / R; input.touch.climb = -dy / R;
  };
  const end = () => { pid.current = null; setKnob({ x: 0, y: 0 }); input.touch.turn = 0; input.touch.climb = 0; };
  const hold = (key: 'drop' | 'boost') => {
    const set = (v: boolean) => { input.touch[key] = v; setHeld(h => ({ ...h, [key]: v })); };
    return { onPointerDown: (e: RPointerEvent) => { (e.target as HTMLElement).setPointerCapture?.(e.pointerId); set(true); }, onPointerUp: () => set(false), onPointerCancel: () => set(false) };
  };
  return (
    <div className="absolute inset-x-0 bottom-0 h-36 pointer-events-none">
      <div ref={baseRef} className="absolute left-5 bottom-5 h-28 w-28 rounded-full bg-white/10 ring-2 ring-white/25 backdrop-blur-sm pointer-events-auto touch-none"
        onPointerDown={e => { pid.current = e.pointerId; (e.target as HTMLElement).setPointerCapture?.(e.pointerId); move(e); }}
        onPointerMove={e => { if (pid.current === e.pointerId) move(e); }} onPointerUp={end} onPointerCancel={end}>
        <div className="absolute left-1/2 top-1/2 h-12 w-12 -ml-6 -mt-6 rounded-full bg-orange-400/80 ring-2 ring-white/60 shadow-lg" style={{ transform: `translate(${knob.x}px, ${knob.y}px)` }} />
      </div>
      <div className="absolute right-5 bottom-5 flex items-end gap-3 pointer-events-auto touch-none">
        <button {...hold('boost')} className={clsx('h-16 w-16 rounded-full grid place-items-center ring-2 ring-white/30 font-bold text-[10px]', held.boost ? 'bg-yellow-400 text-black' : 'bg-yellow-500/40')}><Zap size={20} />TURBO</button>
        <button {...hold('drop')} className={clsx('h-24 w-24 rounded-full grid place-items-center ring-2 ring-white/40 font-black text-xs', held.drop ? 'bg-sky-300 text-sky-950' : 'bg-sky-500/55')}><Droplets size={28} />SOLTAR</button>
      </div>
    </div>
  );
}

export default function Hud({ hud: h, msgs, muted, touch, input, onMute, onPause, onMinimap }: Props) {
  const mapRef = useRef<HTMLCanvasElement>(null);
  useEffect(() => { onMinimap(mapRef.current); return () => onMinimap(null); }, [onMinimap]);
  const ret = !!h && h.retard > 0, hull = h?.hull ?? 100;
  const burnRatio = h ? h.burntPct / h.limitPct : 0;
  return (
    <div className="absolute inset-0 pointer-events-none text-white select-none" style={{ fontFamily: 'system-ui, sans-serif' }}>
      {h && h.hurt > 0.02 && <div className="absolute inset-0" style={{ boxShadow: `inset 0 0 160px rgba(255,40,0,${h.hurt * 0.7})` }} />}
      {h && h.flash > 0.02 && <div className="absolute inset-0 bg-white" style={{ opacity: h.flash * 0.55 }} />}

      <div className={clsx(CARD, 'absolute top-3 left-3 px-4 py-2.5 min-w-[180px]')}>
        <div className="text-[10px] font-mono tracking-[0.3em] text-amber-300/90">PUNTOS</div>
        <div className="text-3xl font-black italic tabular-nums leading-none">{(h?.score ?? 0).toLocaleString('es-ES')}</div>
        <div className="mt-1.5 flex items-center gap-2 text-xs text-white/75"><span className="font-bold text-orange-300">NIVEL {h?.level ?? 1}</span><span className="truncate max-w-[110px]">{h?.levelName}</span></div>
        <div className="mt-1 flex items-center gap-1">
          {[0, 1, 2].map(i => <Plane key={i} size={14} className={i < (h?.lives ?? 3) ? 'text-red-400' : 'text-white/15'} />)}
          {h && h.combo > 2 && <span className="ml-auto text-xs font-black text-sky-300">COMBO x{h.combo - 1}</span>}
        </div>
      </div>

      <div className={clsx(CARD, 'absolute top-[132px] left-3 px-3 py-2 w-[180px] hidden sm:block text-xs')}>
        <div className="flex items-center gap-2"><Flame size={14} className="text-orange-400" /> Focos activos <b className="ml-auto text-orange-300 tabular-nums">{h?.fires ?? 0}</b></div>
        <div className="flex items-center gap-2 mt-1"><Trees size={14} className="text-emerald-400" /> En pie <b className="ml-auto text-emerald-300 tabular-nums">{h?.alive ?? 0} ha</b></div>
        <div className="mt-2 text-[10px] font-mono tracking-widest text-white/60 flex justify-between"><span>QUEMADO</span><span>{Math.round((h?.burntPct ?? 0) * 100)}% / {Math.round((h?.limitPct ?? 0) * 100)}%</span></div>
        <div className="h-2 rounded-full bg-black/50 overflow-hidden ring-1 ring-white/10">
          <div className={clsx('h-full', burnRatio > 0.75 && 'animate-pulse')} style={{ width: `${Math.min(100, burnRatio * 100)}%`, background: 'linear-gradient(90deg,#f59e0b,#ef4444)' }} />
        </div>
      </div>

      <div className="absolute top-3 right-3 flex flex-col items-end gap-2">
        <div className="flex gap-2 pointer-events-auto">
          <button aria-label="Silencio" onClick={onMute} className="h-9 w-9 grid place-items-center rounded-lg bg-black/40 ring-1 ring-white/15 hover:bg-black/60">{muted ? <VolumeX size={16} /> : <Volume2 size={16} />}</button>
          <button aria-label="Pausa" onClick={onPause} className="h-9 w-9 grid place-items-center rounded-lg bg-black/40 ring-1 ring-white/15 hover:bg-black/60"><Pause size={16} /></button>
        </div>
        <div className="relative rounded-xl overflow-hidden ring-2 ring-white/15 bg-black/50 shadow-xl">
          <canvas ref={mapRef} width={256} height={256} className="block w-[110px] h-[110px] sm:w-[150px] sm:h-[150px]" />
          <div className="absolute bottom-1 left-1 flex items-center gap-1 rounded-md bg-black/55 px-1.5 py-0.5 text-[10px] font-mono">
            <Navigation size={12} className="text-sky-300" style={{ transform: `rotate(${-(h?.windDeg ?? 0)}deg)` }} /> {h?.windKmh ?? 0} km/h
          </div>
        </div>
      </div>

      <div className="absolute top-[18%] inset-x-0 flex flex-col items-center gap-1 px-4 text-center">
        {msgs.map(m => <div key={m.id} className={MSG_CLS[m.kind]}>{m.text}</div>)}
      </div>

      <div className={clsx(CARD, 'absolute left-1/2 -translate-x-1/2 w-[min(440px,64vw)] rounded-2xl px-4 py-3', touch ? 'bottom-36' : 'bottom-4')}>
        <div className="flex items-center gap-3">
          <Droplets size={22} className={ret ? 'text-pink-400' : 'text-sky-300'} />
          <div className="flex-1">
            <div className="flex justify-between text-[11px] font-mono tracking-[0.25em]">
              <span className={ret ? 'text-pink-300' : 'text-sky-200'}>{ret ? `RETARDANTE ${Math.ceil(h!.retard)}s` : 'DEPÓSITO'}</span>
              <span className={clsx('font-bold', h?.scooping ? 'text-cyan-200 animate-pulse' : h?.dropping ? 'text-white' : 'text-white/60')}>
                {h?.scooping ? 'CARGANDO…' : h?.dropping ? 'SOLTANDO' : `${Math.round(h?.tank ?? 100)}%`}
              </span>
            </div>
            <div className="h-3.5 rounded-full bg-black/60 ring-1 ring-white/15 overflow-hidden">
              <div className="h-full rounded-full" style={{ width: `${h?.tank ?? 100}%`, background: ret ? 'linear-gradient(90deg,#db2777,#f9a8d4)' : 'linear-gradient(90deg,#0369a1,#38bdf8,#a5f3fc)' }} />
            </div>
          </div>
        </div>
        <div className="mt-2 grid grid-cols-2 gap-4">
          <Bar value={hull} label="CASCO" icon={<Wrench size={14} />} color={hull < 35 ? '#ef4444' : '#4ade80'} pulse={hull < 35} />
          <Bar value={h?.boost ?? 100} label="TURBO" icon={<Zap size={14} />} color="#facc15" />
        </div>
      </div>

      <div className={clsx(CARD, 'absolute right-3 px-3 py-2 font-mono text-right', touch ? 'top-[210px]' : 'bottom-4')}>
        <div className="text-[10px] tracking-widest text-white/55">ALTITUD</div>
        <div className={clsx('text-xl font-bold tabular-nums', (h?.alt ?? 99) < 16 ? 'text-amber-300' : 'text-white')}>{Math.round(h?.alt ?? 0)} m</div>
        <div className="mt-1 text-[10px] tracking-widest text-white/55 flex items-center justify-end gap-1"><Gauge size={11} /> VELOCIDAD</div>
        <div className="text-xl font-bold tabular-nums">{Math.round(h?.speed ?? 0)} <span className="text-xs text-white/60">km/h</span></div>
      </div>

      {touch && input && <TouchControls input={input} />}
    </div>
  );
}

import { Droplets, Flame, Home, Play, RotateCcw, Trophy, Volume2, VolumeX } from 'lucide-react';
import clsx from 'clsx';
import type { ReactNode } from 'react';
import { DIFFS } from '../game/levels';
import type { DiffId, Summary } from '../game/levels';

const TITLE = { fontFamily: '"Avenir Next Condensed", "Arial Narrow", "Roboto Condensed", Impact, system-ui, sans-serif' };

const KEYS: Array<[string, string]> = [
  ['← → / A D', 'Virar'], ['↑ ↓ / W S', 'Subir / bajar'], ['Espacio', 'Soltar agua'],
  ['Shift', 'Turbo'], ['Rasar el lago', 'Cargar el depósito'], ['P / Esc', 'Pausa'],
];

interface MenuProps {
  diff: DiffId; setDiff: (d: DiffId) => void; records: Record<DiffId, number>;
  muted: boolean; onMute: () => void; onPlay: () => void;
}

export function Menu({ diff, setDiff, records, muted, onMute, onPlay }: MenuProps) {
  return (
    <div className="absolute inset-0 overflow-y-auto bg-gradient-to-r from-[#1a0c08]/90 via-[#1a0c08]/45 to-transparent text-white">
      <div className="min-h-full flex items-center p-4 sm:p-10">
        <div className="w-full max-w-[470px]">
          <div className="flex items-center gap-2 text-amber-300 text-xs tracking-[0.45em] font-mono"><Flame size={14} /> BRIGADA FORESTAL AÉREA</div>
          <h1 style={TITLE} className="mt-2 text-6xl sm:text-7xl font-black italic leading-[0.85] tracking-tight">
            <span className="bg-gradient-to-br from-yellow-200 via-amber-400 to-red-500 bg-clip-text text-transparent drop-shadow-[0_4px_24px_rgba(255,110,30,0.45)]">BOMBERO</span>
            <br />
            <span className="bg-gradient-to-br from-sky-200 via-sky-400 to-cyan-600 bg-clip-text text-transparent">AÉREO</span>
          </h1>
          <p className="mt-4 text-sm text-white/80 leading-relaxed">
            El viento empuja las llamas a través del bosque. Rasa el lago con tu hidroavión para llenar el depósito,
            suelta la cortina de agua sobre el frente del incendio y salva cada hectárea… y las cabañas de los guardas.
          </p>

          <div className="mt-5 text-[10px] font-mono tracking-[0.35em] text-white/60">DIFICULTAD</div>
          <div className="mt-2 grid grid-cols-3 gap-2">
            {(Object.keys(DIFFS) as DiffId[]).map(id => (
              <button key={id} onClick={() => setDiff(id)}
                className={clsx('rounded-lg px-2.5 py-2 text-left ring-1 transition', diff === id ? 'bg-gradient-to-br from-amber-500 to-red-600 ring-amber-200 shadow-[0_0_22px_rgba(255,120,40,0.5)]' : 'bg-white/5 ring-white/15 hover:bg-white/10')}>
                <div style={TITLE} className="font-black italic tracking-wider">{DIFFS[id].label.toUpperCase()}</div>
                <div className="text-[10px] leading-tight text-white/80">{DIFFS[id].sub}</div>
              </button>
            ))}
          </div>

          <div className="mt-4 flex items-center gap-3 rounded-lg bg-black/35 ring-1 ring-white/10 px-3 py-2">
            <Trophy className="text-amber-300" size={20} />
            <div className="text-xs text-white/70">Récord ({DIFFS[diff].label})</div>
            <div className="ml-auto font-mono text-lg font-bold text-amber-200">{records[diff].toLocaleString('es-ES')}</div>
            <button aria-label="Silencio" onClick={onMute} className="h-8 w-8 grid place-items-center rounded-md bg-white/10 ring-1 ring-white/20">
              {muted ? <VolumeX size={16} /> : <Volume2 size={16} />}
            </button>
          </div>

          <div className="mt-4 grid grid-cols-2 gap-x-4 gap-y-1.5 text-xs">
            {KEYS.map(([k, v]) => (
              <div key={k} className="flex items-center gap-2">
                <kbd className="rounded bg-white/10 ring-1 ring-white/20 px-1.5 py-0.5 font-mono text-[10px] text-amber-100 whitespace-nowrap">{k}</kbd>
                <span className="text-white/75">{v}</span>
              </div>
            ))}
          </div>

          <button onClick={onPlay}
            className="mt-6 w-full flex items-center justify-center gap-3 rounded-xl bg-gradient-to-r from-amber-400 via-orange-500 to-red-600 py-4 text-2xl font-black italic tracking-wider shadow-[0_8px_40px_rgba(255,100,30,0.55)] hover:brightness-110 active:scale-[0.99] transition"
            style={TITLE}>
            <Play size={26} fill="currentColor" /> Jugar
          </button>
          <div className="mt-3 flex items-center gap-2 text-[11px] text-white/55"><Droplets size={13} className="text-sky-300" /> Anillos: agua · retardante · reparación · turbo</div>
        </div>
      </div>
    </div>
  );
}

function Panel({ children }: { children: ReactNode }) {
  return (
    <div className="absolute inset-0 grid place-items-center bg-black/55 backdrop-blur-sm p-4 text-white">
      <div className="w-full max-w-sm rounded-2xl bg-gradient-to-b from-[#2a140c] to-[#120806] ring-1 ring-amber-200/20 p-6 shadow-2xl">{children}</div>
    </div>
  );
}

const btn = 'w-full flex items-center justify-center gap-2 rounded-xl py-3 font-bold transition';

export function PauseScreen({ onResume, onRestart, onMenu }: { onResume: () => void; onRestart: () => void; onMenu: () => void }) {
  return (
    <Panel>
      <h2 style={TITLE} className="text-4xl font-black italic text-center text-amber-200">PAUSA</h2>
      <div className="mt-5 space-y-2">
        <button onClick={onResume} className={clsx(btn, 'bg-gradient-to-r from-amber-400 to-orange-600')}><Play size={18} /> Continuar</button>
        <button onClick={onRestart} className={clsx(btn, 'bg-white/10 ring-1 ring-white/15 hover:bg-white/15')}><RotateCcw size={18} /> Reiniciar</button>
        <button onClick={onMenu} className={clsx(btn, 'bg-white/10 ring-1 ring-white/15 hover:bg-white/15')}><Home size={18} /> Menú</button>
      </div>
    </Panel>
  );
}

export function GameOverScreen({ s, onRetry, onMenu }: { s: Summary; onRetry: () => void; onMenu: () => void }) {
  const mm = Math.floor(s.time / 60), ss = Math.floor(s.time % 60).toString().padStart(2, '0');
  const rows: Array<[string, string]> = [
    ['Nivel alcanzado', String(s.level)], ['Hectáreas salvadas', `${s.saved} ha`], ['Celdas apagadas', String(s.extinguished)],
    ['Cabañas protegidas', String(s.cabins)], ['Tiempo de vuelo', `${mm}:${ss}`], [`Récord (${DIFFS[s.diff].label})`, s.record.toLocaleString('es-ES')],
  ];
  return (
    <Panel>
      <div className="text-center text-xs font-mono tracking-[0.35em] text-red-300">FIN DE LA MISIÓN</div>
      <div className="text-center text-sm text-white/70 mt-1">{s.reason}</div>
      <div style={TITLE} className="mt-3 text-center text-6xl font-black italic text-amber-200 tabular-nums">{s.score.toLocaleString('es-ES')}</div>
      {s.newRecord && <div className="mt-1 text-center text-sm font-black text-yellow-300 animate-pulse">¡NUEVO RÉCORD!</div>}
      <div className="mt-4 divide-y divide-white/10 rounded-lg bg-black/30 ring-1 ring-white/10">
        {rows.map(([k, v]) => <div key={k} className="flex justify-between px-3 py-1.5 text-sm"><span className="text-white/65">{k}</span><b>{v}</b></div>)}
      </div>
      <div className="mt-5 space-y-2">
        <button onClick={onRetry} className={clsx(btn, 'bg-gradient-to-r from-amber-400 to-orange-600')}><RotateCcw size={18} /> Reintentar</button>
        <button onClick={onMenu} className={clsx(btn, 'bg-white/10 ring-1 ring-white/15 hover:bg-white/15')}><Home size={18} /> Menú</button>
      </div>
    </Panel>
  );
}

/** Audio procedural (Web Audio API): motor, crepitar del fuego, agua, avisos y efectos. */
interface Loop { src: AudioScheduledSourceNode; gain: GainNode; filter: BiquadFilterNode; osc?: OscillatorNode }

export class Sfx {
  ctx: AudioContext | null = null; muted = false; private master: GainNode | null = null;
  private noise: AudioBuffer | null = null;
  private engine: Loop | null = null; private fire: Loop | null = null; private rush: Loop | null = null;
  private crackleT = 0;

  /** Llamar en el primer gesto del usuario. */
  unlock() {
    if (this.ctx) { if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {}); return; }
    const AC: typeof AudioContext | undefined = (window as any).AudioContext || (window as any).webkitAudioContext;
    if (!AC) return;
    try { this.ctx = new AC(); } catch { return; }
    const c = this.ctx;
    this.master = c.createGain(); this.master.gain.value = this.muted ? 0 : 0.5; this.master.connect(c.destination);
    const len = c.sampleRate * 2; this.noise = c.createBuffer(1, len, c.sampleRate);
    const d = this.noise.getChannelData(0);
    for (let i = 0; i < len; i++) d[i] = Math.random() * 2 - 1;
    // Motor: diente de sierra grave filtrado
    const o = c.createOscillator(); o.type = 'sawtooth'; o.frequency.value = 58;
    this.engine = this.loop(o, 'lowpass', 420, 0); this.engine.osc = o;
    this.fire = this.loop(this.noiseSrc(), 'bandpass', 900, 0);
    this.rush = this.loop(this.noiseSrc(), 'highpass', 1400, 0);
  }

  private noiseSrc() { const n = this.ctx!.createBufferSource(); n.buffer = this.noise; n.loop = true; return n; }
  private loop(src: AudioScheduledSourceNode, type: BiquadFilterType, freq: number, vol: number): Loop {
    const c = this.ctx!; const filter = c.createBiquadFilter(); filter.type = type; filter.frequency.value = freq;
    const gain = c.createGain(); gain.gain.value = vol;
    src.connect(filter); filter.connect(gain); gain.connect(this.master!); src.start();
    return { src, gain, filter };
  }

  setMuted(m: boolean) {
    this.muted = m;
    if (this.master && this.ctx) this.master.gain.setTargetAtTime(m ? 0 : 0.5, this.ctx.currentTime, 0.05);
  }

  /** Sonidos continuos: motor según velocidad, fuego cercano, agua (carga/descarga). */
  setLoops(active: boolean, speed: number, boost: boolean, fire: number, water: number) {
    if (!this.ctx || !this.engine || !this.fire || !this.rush) return;
    const t = this.ctx.currentTime;
    this.engine.osc!.frequency.setTargetAtTime(48 + speed * 0.7 + (boost ? 18 : 0), t, 0.2);
    this.engine.filter.frequency.setTargetAtTime(boost ? 1100 : 480, t, 0.2);
    this.engine.gain.gain.setTargetAtTime(active ? 0.13 : 0, t, 0.3);
    this.fire.gain.gain.setTargetAtTime(active ? Math.min(0.35, fire * 0.35) : 0, t, 0.3);
    this.rush.gain.gain.setTargetAtTime(active ? water * 0.22 : 0, t, 0.1); this.crackleT -= 0.016;
    if (active && fire > 0.1 && this.crackleT <= 0 && Math.random() < fire) {
      this.crackleT = 0.05 + Math.random() * 0.12;
      this.burst(0.03, 2500 + Math.random() * 2500, 0.25 * fire, 'bandpass');
    }
  }

  private burst(dur: number, freq: number, vol: number, type: BiquadFilterType = 'lowpass') {
    if (!this.ctx || !this.master || !this.noise) return;
    const c = this.ctx, t = c.currentTime; const n = this.noiseSrc(); n.loop = false;
    const f = c.createBiquadFilter(); f.type = type; f.frequency.value = freq;
    const g = c.createGain(); g.gain.setValueAtTime(vol, t); g.gain.exponentialRampToValueAtTime(0.001, t + dur);
    n.connect(f); f.connect(g); g.connect(this.master); n.start(t); n.stop(t + dur + 0.05);
  }

  private tone(freq: number, dur: number, type: OscillatorType, vol: number, slide = 0, delay = 0) {
    if (!this.ctx || !this.master) return;
    const c = this.ctx, t = c.currentTime + delay;
    const o = c.createOscillator(); o.type = type; o.frequency.setValueAtTime(freq, t);
    if (slide) o.frequency.exponentialRampToValueAtTime(Math.max(20, freq + slide), t + dur);
    const g = c.createGain(); g.gain.setValueAtTime(0.0001, t); g.gain.exponentialRampToValueAtTime(vol, t + 0.01);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master); o.start(t); o.stop(t + dur + 0.05);
  }

  hiss() { this.burst(0.7, 3200, 0.3, 'highpass'); }
  splash() { this.burst(0.5, 900, 0.35); }
  pickup() { [660, 880, 1320].forEach((f, i) => this.tone(f, 0.18, 'triangle', 0.2, 0, i * 0.07)); }
  warn() { this.tone(880, 0.12, 'square', 0.08); this.tone(660, 0.12, 'square', 0.08, 0, 0.14); }
  hit() { this.burst(0.25, 500, 0.5); this.tone(120, 0.2, 'sawtooth', 0.15, -60); }
  crash() { this.burst(1.4, 300, 0.9); this.tone(90, 1.0, 'sawtooth', 0.3, -60); }
  thunder() { this.burst(2.2, 180, 0.9); this.burst(0.3, 2000, 0.4, 'highpass'); }
  cabin() { this.tone(300, 0.5, 'sawtooth', 0.15, -180); }
  levelUp() { [523, 659, 784, 1047].forEach((f, i) => this.tone(f, 0.35, 'triangle', 0.22, 0, i * 0.12)); }
  gameOver() { [392, 330, 262, 196].forEach((f, i) => this.tone(f, 0.45, 'triangle', 0.22, 0, i * 0.2)); }

  dispose() {
    for (const l of [this.engine, this.fire, this.rush]) { try { l?.src.stop(); } catch { /* ya parado */ } }
    this.ctx?.close().catch(() => {}); this.ctx = null;
  }
}

import * as THREE from 'three';
import { Particles, P, makeSpriteTex } from './particles';
import { Forest, CELL } from './forest';
import { heightAt, WATER_Y, FOG_LIN } from './world';
import { toSRGB } from './three-compat';

interface Packet { x: number; y: number; z: number; vx: number; vy: number; vz: number; ret: boolean }
export interface DropHit { x: number; z: number; hiss: number; out: number }

const R = Math.random; const rs = (s: number) => (R() - 0.5) * s;

/** Partículas del juego: incendios, humo, cortina de agua, salpicaduras y explosiones. */
export class Effects {
  add: Particles; norm: Particles; private texF: THREE.Texture; private texP: THREE.Texture;
  private packets: Packet[] = []; private smolder: Array<{ x: number; z: number; y: number; t: number }> = [];
  private packetT = 0;

  constructor(scene: THREE.Scene, private forest: Forest) {
    this.texF = makeSpriteTex('fire'); this.texP = makeSpriteTex('puff'); const fog = toSRGB(FOG_LIN);
    this.norm = new Particles(scene, 2800, false, this.texP, fog);
    this.add = new Particles(scene, 2800, true, this.texF, fog);
  }

  setScale(px: number) { this.add.setScale(px); this.norm.setScale(px); }

  /** Celda recién quemada: humo residual durante un rato. */
  burnt(x: number, z: number) {
    if (this.smolder.length > 70) this.smolder.shift();
    this.smolder.push({ x, z, y: heightAt(x, z), t: 10 + R() * 8 });
  }

  /** Llamas, resplandor, pavesas y columnas de humo de todas las celdas en llamas. */
  fires(dt: number, cam: THREE.Vector3) {
    const f = this.forest, w = f.wind, wx = w.x * w.str, wz = w.z * w.str;
    for (const i of f.burning) {
      const [x, z] = f.center(i); const d2 = (x - cam.x) ** 2 + (z - cam.z) ** 2;
      if (d2 > 1500 * 1500) continue;
      const h = f.heat[i], g = f.ground[i], near = d2 < 550 * 550 ? 1 : 0.4; let n = dt * (6 + 12 * h) * near;
      while (n > 0) {
        if (n < 1 && R() > n) break;
        n -= 1;
        this.add.emit(P.FLAME, x + rs(CELL * 0.9), g + 2 + R() * 10 * h, z + rs(CELL * 0.9), wx * 3 + rs(3), 5 + R() * 9, wz * 3 + rs(3), 0.55 + R() * 0.6, 7 + 9 * h, 2);
      }
      if (R() < dt * 2.5 * near) this.add.emit(P.GLOW, x + rs(6), g + 6, z + rs(6), 0, 1, 0, 0.7, 26 + 34 * h, 40 + 40 * h);
      if (R() < dt * 2.5 * h * near) this.add.emit(P.EMBER, x + rs(CELL), g + 10, z + rs(CELL), wx * 6 + rs(6), 12 + R() * 14, wz * 6 + rs(6), 1.5 + R() * 1.5, 1.6, 0.8);
      if (R() < dt * (0.7 + 1.8 * h) * (near > 0.5 ? 1 : 0.6)) {
        this.norm.emit(P.SMOKE, x + rs(CELL * 0.8), g + 12 + R() * 4, z + rs(CELL * 0.8), wx * 5, 8 + R() * 6, wz * 5, 6.5 + R() * 3.5, 14 + 8 * h, 60 + 40 * h);
      }
    }
    for (let k = this.smolder.length - 1; k >= 0; k--) {
      const s = this.smolder[k]; s.t -= dt;
      if (s.t <= 0) { this.smolder.splice(k, 1); continue; }
      if (R() < dt * 0.6) this.norm.emit(P.SMOKE, s.x + rs(14), s.y + 4, s.z + rs(14), wx * 4, 5 + R() * 3, wz * 4, 5 + R() * 3, 8, 34);
    }
  }

  /** Cortina de agua (o retardante rosa) bajo el avión mientras se suelta. */
  drop(dt: number, belly: THREE.Vector3, vel: THREE.Vector3, ret: boolean) {
    const type = ret ? P.PINK : P.WATER; let n = Math.ceil(dt * 220);
    while (n-- > 0) {
      const s = R();
      this.norm.emit(type, belly.x + rs(3), belly.y - R() * 2, belly.z + rs(3), vel.x * 0.85 + rs(5), vel.y * 0.4 - 2 - R() * 5, vel.z * 0.85 + rs(5), 1.4 + R() * 1.1, 2 + s * 2, 7 + s * 10);
    }
    this.packetT -= dt;
    if (this.packetT <= 0) {
      this.packetT = 0.06;
      if (this.packets.length < 90) this.packets.push({ x: belly.x, y: belly.y, z: belly.z, vx: vel.x * 0.85, vy: vel.y * 0.4 - 3, vz: vel.z * 0.85, ret });
    }
  }

  /** Simula los "paquetes" de agua y aplica su efecto al tocar el bosque. */
  updatePackets(dt: number): DropHit[] {
    const hits: DropHit[] = []; const f = this.forest, w = f.wind;
    for (let k = this.packets.length - 1; k >= 0; k--) {
      const p = this.packets[k]; const dr = 1 - 0.35 * dt;
      p.vx = p.vx * dr + w.x * w.str * 2 * dt; p.vz = p.vz * dr + w.z * w.str * 2 * dt; p.vy -= 26 * dt;
      p.x += p.vx * dt; p.y += p.vy * dt; p.z += p.vz * dt; const g = heightAt(p.x, p.z);
      const top = Math.max(g, WATER_Y, f.treeTop(p.x, p.z) - 3);
      if (p.y > top) continue;
      this.packets.splice(k, 1);
      if (g < WATER_Y) { this.splash(p.x, WATER_Y, p.z, 2); continue; }
      const r = f.applyWater(p.x, p.z, p.ret ? 30 : 21, p.ret ? 1.2 : 0.8, p.ret ? 45 : 26);
      if (r.hiss > 0) for (let j = 0; j < 5; j++) this.norm.emit(P.STEAM, p.x + rs(20), top + R() * 6, p.z + rs(20), rs(4), 6 + R() * 8, rs(4), 2.5 + R() * 2, 14, 46);
      else this.splash(p.x, top, p.z, 1);
      hits.push({ x: p.x, z: p.z, hiss: r.hiss, out: r.out });
    }
    return hits;
  }

  splash(x: number, y: number, z: number, k: number) {
    for (let j = 0; j < 4 * k; j++) this.norm.emit(P.SPRAY, x + rs(12), y + 1, z + rs(12), rs(10), 8 + R() * 10, rs(10), 0.9 + R() * 0.6, 4, 16);
  }

  /** Estela de espuma al rasar el lago con los flotadores. */
  scoop(dt: number, pos: THREE.Vector3, fwd: THREE.Vector3) {
    let n = Math.ceil(dt * 70);
    while (n-- > 0) {
      const side = R() < 0.5 ? -1 : 1;
      const x = pos.x + fwd.z * side * 2.3 - fwd.x * (2 + R() * 3), z = pos.z - fwd.x * side * 2.3 - fwd.z * (2 + R() * 3);
      this.norm.emit(P.SPRAY, x, WATER_Y + 0.6, z, fwd.z * side * (4 + R() * 6) - fwd.x * 8, 3 + R() * 7, -fwd.x * side * (4 + R() * 6) - fwd.z * 8, 0.7 + R() * 0.7, 2.5, 11);
    }
  }

  explosion(p: THREE.Vector3) {
    for (let j = 0; j < 45; j++) this.add.emit(P.FLAME, p.x, p.y, p.z, rs(50), rs(40) + 10, rs(50), 0.6 + R() * 0.7, 10, 4);
    for (let j = 0; j < 4; j++) this.add.emit(P.GLOW, p.x, p.y, p.z, 0, 0, 0, 0.6, 50, 120);
    for (let j = 0; j < 25; j++) this.norm.emit(P.SMOKE, p.x + rs(10), p.y, p.z + rs(10), rs(16), 6 + R() * 10, rs(16), 3 + R() * 3, 12, 50);
    for (let j = 0; j < 25; j++) this.norm.emit(P.DEBRIS, p.x, p.y, p.z, rs(40), 10 + R() * 25, rs(40), 1.5 + R(), 1.5, 1);
  }
  leaves(p: THREE.Vector3) {
    for (let j = 0; j < 6; j++) this.norm.emit(P.DEBRIS, p.x + rs(4), p.y - 2, p.z + rs(4), rs(20), 6 + R() * 10, rs(20), 1 + R(), 1.6, 1);
  }
  damageTrail(p: THREE.Vector3, dt: number) {
    if (R() < dt * 25) this.norm.emit(P.SMOKE, p.x + rs(2), p.y, p.z + rs(2), 0, 2, 0, 1.6, 2.5, 12);
  }
  sparkle(p: THREE.Vector3) {
    for (let j = 0; j < 30; j++) this.add.emit(P.SPARK, p.x, p.y, p.z, rs(36), rs(36), rs(36), 0.7 + R() * 0.5, 3, 0.5);
    this.add.emit(P.GLOW, p.x, p.y, p.z, 0, 0, 0, 0.5, 30, 70);
  }
  strike(x: number, y: number, z: number) {
    for (let j = 0; j < 3; j++) this.add.emit(P.GLOW, x, y + 4, z, 0, 0, 0, 0.5, 80, 160);
    for (let j = 0; j < 30; j++) this.add.emit(P.EMBER, x, y + 2, z, rs(40), 10 + R() * 20, rs(40), 1 + R(), 2.2, 1);
  }

  /** Simula unos segundos para que el incendio ya tenga humo al empezar. */
  prewarm(sec: number, cam: THREE.Vector3) {
    for (let t = 0; t < sec; t += 0.1) { this.fires(0.1, cam); this.update(0.1); }
  }

  update(dt: number) {
    const w = this.forest.wind; this.add.update(dt, w.x * w.str, w.z * w.str);
    this.norm.update(dt, w.x * w.str, w.z * w.str);
  }

  clear() { this.add.clear(); this.norm.clear(); this.packets = []; this.smolder = []; }

  dispose() { this.add.dispose(); this.norm.dispose(); this.texF.dispose(); this.texP.dispose(); }
}

import * as THREE from 'three';
import { setupRenderer } from './three-compat';
import { World, LAKES, MAP_R, heightAt, mulberry32 } from './world';
import { Forest, FIRE, GRID, CELL, G_HALF } from './forest';
import { Effects } from './effects';
import { Plane } from './plane';
import { Pickups, PICK_INFO } from './pickups';
import { Input } from './input';
import { Sfx } from './audio';
import { DIFFS, levelConfig, loadRecords, saveRecord } from './levels';
import type { DiffId, HudData, LevelCfg, Mode, MsgKind, Summary } from './levels';

export interface GameCallbacks {
  onHud: (d: HudData) => void; onMessage: (text: string, kind: MsgKind) => void; onGameOver: (s: Summary) => void;
}

const _v = new THREE.Vector3(), _w = new THREE.Vector3(), _look = new THREE.Vector3();
const rs = (s: number) => (Math.random() - 0.5) * s;

export class Game {
  mode: Mode = 'menu'; input = new Input(); sfx = new Sfx(); private renderer: THREE.WebGLRenderer;
  private scene = new THREE.Scene(); private camera: THREE.PerspectiveCamera;
  private world: World; private forest: Forest; private fx: Effects; private plane: Plane; private pickups: Pickups;
  private container: HTMLElement; private ro: ResizeObserver; private raf = 0;
  private clock = new THREE.Clock(); private t = 0; private cb: GameCallbacks;
  private diffId: DiffId = 'normal'; private cfg: LevelCfg = levelConfig(1, 'normal');
  private level = 1; private score = 0; private lives = 3; private combo = 1; private comboT = 0;
  private playT = 0; private levelT = 0; private retT = 0; private lightT = 0;
  private interT = -1; private deadT = -1; private overT = -1; private overReason = '';
  private hurt = 0; private flash = 0; private shake = 0; private warnT = 0; private hitSndT = 0;
  private savedTotal = 0; private outTotal = 0; private cabinsSaved = 0;
  private heatWarn = false; private treeWarn = false; private edgeWarn = false; private dropping = false;
  private nearFire = 0; private nearT = 0; private spawn = { x: 0, z: 0, yaw: 0, dx: 0, dz: 1 };
  private firePos = new THREE.Vector3(); private camPos = new THREE.Vector3(); private camInit = false;
  private hudT = 0; private mapT = 0; private minimap: HTMLCanvasElement | null = null;
  private mapCv = document.createElement('canvas'); private mapImg: ImageData;

  constructor(container: HTMLElement, cb: GameCallbacks) {
    this.container = container; this.cb = cb;
    this.renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
    setupRenderer(this.renderer); this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    this.renderer.domElement.style.display = 'block'; container.appendChild(this.renderer.domElement);
    this.camera = new THREE.PerspectiveCamera(62, 1, 0.5, 3200); this.world = new World(this.scene);
    this.forest = new Forest(this.scene, {
      onBurnt: (x, z) => { this.world.scorch(x, z, 15); this.fx.burnt(x, z); },
      onCabinLost: () => { if (this.mode === 'play') { this.score = Math.max(0, this.score - 400); this.cb.onMessage('¡Cabaña perdida! −400', 'warn'); this.sfx.cabin(); } },
    });
    this.fx = new Effects(this.scene, this.forest); this.plane = new Plane(this.scene);
    this.pickups = new Pickups(this.scene); this.mapCv.width = this.mapCv.height = GRID;
    this.mapImg = this.mapCv.getContext('2d')!.createImageData(GRID, GRID);
    const L = LAKES[0], d = Math.hypot(L.x, L.z);
    this.spawn = { x: L.x - (L.x / d) * L.r * 0.5, z: L.z - (L.z / d) * L.r * 0.5, yaw: Math.atan2(-L.x, -L.z), dx: -L.x / d, dz: -L.z / d };
    this.setupLevel(1, 'normal', 11); this.forest.simulate = false; this.input.attach();
    this.ro = new ResizeObserver(() => this.resize()); this.ro.observe(container); this.resize(); this.loop();
  }

  setMinimap(c: HTMLCanvasElement | null) { this.minimap = c; }
  setMuted(m: boolean) { this.sfx.setMuted(m); }

  private resize() {
    const w = Math.max(1, this.container.clientWidth), h = Math.max(1, this.container.clientHeight);
    this.renderer.setSize(w, h, false);
    this.renderer.domElement.style.width = '100%'; this.renderer.domElement.style.height = '100%';
    this.camera.aspect = w / h; this.camera.updateProjectionMatrix();
    const px = h * this.renderer.getPixelRatio() / (2 * Math.tan(THREE.MathUtils.degToRad(this.camera.fov) / 2));
    this.fx.setScale(px);
  }

  private setupLevel(level: number, diff: DiffId, seed: number) {
    this.cfg = levelConfig(level, diff); const s = this.spawn;
    this.forest.reset({
      seed, clusters: this.cfg.clusters, size: this.cfg.size, spread: this.cfg.spread, windStr: this.cfg.windStr,
      windAng: seed * 1.7, startX: s.x, startZ: s.z, dirX: s.dx, dirZ: s.dz,
    });
    this.forest.igniteCluster(this.forest.burning[0] ?? 0, 2); this.world.resetScorch(); this.fx.clear();
    const [fx, fz] = this.forest.center(this.forest.burning[0] ?? 0); this.firePos.set(fx, heightAt(fx, fz), fz);
    this.plane.reset(s.x, 34, s.z, s.yaw); this.pickups.reset(mulberry32(seed + 3), this.plane.pos);
    this.fx.prewarm(4, this.plane.pos);
    this.lightT = this.cfg.lightning; this.levelT = 0; this.retT = 0; this.camInit = false;
  }

  start(diff: DiffId) {
    this.sfx.unlock();
    this.diffId = diff; this.level = 1; this.score = 0; this.lives = 3; this.combo = 1; this.playT = 0;
    this.savedTotal = 0; this.outTotal = 0; this.cabinsSaved = 0; this.interT = -1; this.deadT = -1; this.overT = -1;
    this.hurt = 0; this.flash = 0; this.input.reset(); this.setupLevel(1, diff, 1 + Math.floor(Math.random() * 9999));
    this.forest.simulate = true; this.mode = 'play'; this.announce();
  }

  private announce() {
    const c = this.cfg;
    this.cb.onMessage(`Nivel ${this.level} · ${c.name}`, 'big');
    this.cb.onMessage(`Viento ${Math.round(c.windStr * 30)} km/h · ${c.clusters} focos activos`, 'info');
    if (c.lightning > 0) this.cb.onMessage('Tormenta seca: los rayos pueden encender nuevos focos', 'warn');
  }

  pause() { if (this.mode === 'play') { this.mode = 'paused'; this.input.reset(); } }
  resume() { if (this.mode === 'paused') { this.mode = 'play'; this.clock.getDelta(); } }
  toMenu() {
    this.mode = 'menu'; this.input.reset(); this.setupLevel(1, 'normal', 11); this.forest.simulate = false;
  }

  private warn(text: string) {
    if (this.warnT > 0) return;
    this.warnT = 2.2; this.cb.onMessage(text, 'warn'); this.sfx.warn();
  }

  private loop = () => {
    this.raf = requestAnimationFrame(this.loop); const dt = Math.min(0.05, this.clock.getDelta());
    if (this.mode !== 'paused') {
      this.t += dt;
      if (this.mode === 'play') this.step(dt); else this.menuStep(dt);
      this.fx.fires(dt, this.camera.position); this.fx.update(dt);
    }
    const glow = Math.min(1, this.forest.burning.length / 25);
    this.world.update(dt, this.t, this.camera.position, this.firePos, glow);
