  /** Menú: el hidroavión patrulla en círculos sobre el incendio. */
  private menuStep(dt: number) {
    const p = this.plane, a = this.t * 0.35, c = this.firePos;
    p.pos.set(c.x + Math.cos(a) * 110, c.y + 55, c.z + Math.sin(a) * 110);
    p.yaw = Math.atan2(-Math.sin(a), Math.cos(a)); p.roll = -0.45; p.pitch = 0; p.sync(this.t);
    this.forest.update(dt, this.t); this.pickups.update(dt, this.t, null); const b = this.t * 0.08;
    this.camera.position.set(c.x + Math.cos(b) * 210 - 60, c.y + 70, c.z + Math.sin(b) * 210);
    this.camera.lookAt(c.x, c.y + 30, c.z); this.nearFire = 0;
  }

  private step(dt: number) {
    const p = this.plane, f = this.forest, inp = this.input.state, dmg = DIFFS[this.diffId].dmg; this.input.update();
    this.playT += dt; this.levelT += dt;
    this.warnT -= dt; this.hitSndT -= dt; this.retT = Math.max(0, this.retT - dt);
    this.hurt = Math.max(0, this.hurt - dt * 1.5); this.flash = Math.max(0, this.flash - dt * 3);
    this.heatWarn = false; this.treeWarn = false; this.edgeWarn = false; this.dropping = false;

