        this.edgeWarn = true; let d = Math.atan2(-p.pos.x, -p.pos.z) - p.yaw;
        d = Math.atan2(Math.sin(d), Math.cos(d)); p.yaw += Math.sign(d) * Math.min(Math.abs(d), dt * 1.4);
      }
      const ground = p.update(dt, inp, f.wind, this.t); const fwd = p.forward;
      const top = f.treeTop(p.pos.x, p.pos.z);
      if (p.pos.y - 1.5 < top) { this.damage(26 * dt * dmg); this.treeWarn = true; this.fx.leaves(p.pos); p.speed *= 1 - dt * 0.8; this.shake = Math.max(this.shake, 0.4); }
      if (p.groundHit > 0) { this.damage(p.groundHit * 1.6 * dmg); this.shake = 1; if (this.hitSndT <= 0) { this.sfx.hit(); this.hitSndT = 0.6; } }
      const ci = f.cellAt(p.pos.x, p.pos.z);
