        _w.copy(fwd).multiplyScalar(p.speed); _w.y = p.vy; this.fx.drop(dt, p.belly(_v), _w, this.retT > 0);
      }
      if (p.scooping && p.tank < 100) this.fx.scoop(dt, p.pos, fwd);
      if (p.hull < 35) this.fx.damageTrail(p.pos, dt);
      if (p.overWater && p.tank < 30 && p.pos.y > 30) this.warn('Baja al lago y rasa el agua para cargar');
      if (this.treeWarn) this.warn('¡Cuidado con las copas!');
      else if (this.heatWarn) this.warn('¡Calor extremo! Sube un poco');
      else if (this.edgeWarn) this.warn('Límite de la zona: volviendo');
