  private updateCamera(dt: number) {
    const p = this.plane, fwd = p.forward; _v.copy(p.pos).addScaledVector(fwd, -30); _v.y += 10 - p.vy * 0.12;
    if (!this.camInit) { this.camPos.copy(_v); this.camInit = true; }
