      hull: Math.max(0, p.hull), boost: p.boost, alt: Math.max(0, p.pos.y - Math.max(0, heightAt(p.pos.x, p.pos.z))),
      speed: p.speed * 3.6, fires: f.burning.length, burntPct: f.total ? f.burnt / f.total : 0, limitPct: this.cfg.limit,
      alive: f.alive, windDeg: THREE.MathUtils.radToDeg(windAbs - p.yaw), windKmh: Math.round(w.str * 30), combo: this.combo,
      scooping: p.scooping && p.tank < 100, dropping: this.dropping, heatWarn: this.heatWarn, treeWarn: this.treeWarn,
