    const mats = base.map(c => new THREE.MeshLambertMaterial({ color: c.clone() }));
    const walls = new THREE.Mesh(new THREE.BoxGeometry(8, 5, 7), mats[0]); walls.position.y = 2.5;
    const roof = new THREE.Mesh(new THREE.CylinderGeometry(5.6, 5.6, 9.4, 3), mats[1]);
    roof.rotation.z = Math.PI / 2; roof.position.y = 6.6; roof.scale.set(1, 1, 0.75);
    const chim = new THREE.Mesh(new THREE.BoxGeometry(1.2, 3.5, 1.2), mats[2]); chim.position.set(2.3, 7.5, 1.2);
    g.add(walls, roof, chim); g.visible = false; this.scene.add(g);
    return { cell: -1, group: g, mats, base, lost: false };
  }

  private setTree(t: number, charred: boolean, hidden = false) {
    const a = this.inst, o = t * 8, s = hidden ? 0.001 : a[o + 3]; _q.setFromAxisAngle(_up, a[o + 4]);
    _s.set(s * (charred ? 0.5 : 1), s * (charred ? 0.62 : 1), s * (charred ? 0.5 : 1));
    _m.compose(_p.set(a[o], a[o + 1], a[o + 2]), _q, _s); this.mesh.setMatrixAt(t, _m);
  }

  /** Color base de un árbol según el tipo de celda y una variación aleatoria. */
  private baseColor(t: number, cell: number, out: THREE.Color) {
    const o = t * 8, v = this.inst[o + 5], w = this.inst[o + 6];
    if (this.kind[cell] === 1) return out.setRGB(0.025 + v * 0.02, 0.085 + w * 0.04, 0.06 + v * 0.03);
    if (this.inst[o + 7] > 0.975) return out.setRGB(0.2 + v * 0.08, 0.15 + w * 0.05, 0.025);
    return out.setRGB(0.05 + v * 0.05, 0.13 + w * 0.08, 0.035 + v * 0.03);
  }

  private paintCell(i: number) {
    const st = this.state[i];
    for (let k = 0; k < this.tCount[i]; k++) {
      const t = this.tStart[i] + k;
      if (st === BURNT) _c.setRGB(0.045, 0.038, 0.034);
      else { this.baseColor(t, i, _c); if (st === WET) _c.setRGB(_c.r * 0.6, _c.g * 0.85 + 0.02, _c.b + 0.07); }
      this.mesh.setColorAt(t, _c);
    }
    if (this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  reset(cfg: FireSetup) {
    this.rng = mulberry32(cfg.seed); const off = this.rng() * 500;
    this.burnt = 0; this.extinguished = 0; this.total = 0; this.burning = []; this.acc = 0;
    this.spreadMul = cfg.spread; this.wind = { x: Math.cos(cfg.windAng), z: Math.sin(cfg.windAng), str: cfg.windStr };
    for (let i = 0; i < N; i++) {
      const f = this.forested[i]; this.state[i] = f ? TREE : NONE; this.heat[i] = 0; this.wet[i] = 0;
      const [x, z] = this.center(i); this.kind[i] = f && fbm(x * 0.008 + off, z * 0.008, 2) > 0.6 ? 1 : 0;
      this.fuel[i] = 1;
      if (f) this.total++;
      for (let k = 0; k < this.tCount[i]; k++) this.setTree(this.tStart[i] + k, false);
      if (f) this.paintCell(i);
    }
    // Cabañas en celdas boscosas al azar
    for (const c of this.cabins) {
      let cell = -1;
      for (let tries = 0; tries < 200 && cell < 0; tries++) {
        const i = Math.floor(this.rng() * N); const [x, z] = this.center(i);
        if (this.forested[i] && Math.hypot(x - cfg.startX, z - cfg.startZ) > 160 && !this.cabins.some(o => o.cell === i)) cell = i;
      }
      c.cell = cell; c.lost = false; c.group.visible = cell >= 0; c.mats.forEach((m, k) => m.color.copy(c.base[k]));
      if (cell < 0) continue;
      const [x, z] = this.center(cell);
      c.group.position.set(x, this.ground[cell] - 0.4, z); c.group.rotation.y = this.rng() * 6.28;
      for (let k = 0; k < this.tCount[cell]; k++) this.setTree(this.tStart[cell] + k, false, true);
    }
    this.mesh.instanceMatrix.needsUpdate = true;
    // Focos: el primero delante del punto de salida, el resto lejos
    for (let k = 0; k < cfg.clusters; k++) {
      let cell = -1;
      if (k === 0) {
        for (let d = 115; d < 420 && cell < 0; d += 10) {
          const i = this.cellAt(cfg.startX + cfg.dirX * d, cfg.startZ + cfg.dirZ * d);
          if (i >= 0 && this.forested[i]) cell = i;
        }
      }
      for (let tries = 0; tries < 300 && cell < 0; tries++) {
        const i = Math.floor(this.rng() * N); const [x, z] = this.center(i);
        if (this.forested[i] && this.state[i] === TREE && Math.hypot(x - cfg.startX, z - cfg.startZ) > 260) cell = i;
      }
      if (cell >= 0) this.igniteCluster(cell, cfg.size);
    }
  }

  igniteCluster(cell: number, size: number) {
    const cx = cell % GRID, cz = Math.floor(cell / GRID);
    for (let dz = -size; dz <= size; dz++) for (let dx = -size; dx <= size; dx++) {
      if (dx * dx + dz * dz > size * size + 0.5) continue;
      const x = cx + dx, z = cz + dz;
      if (x < 0 || z < 0 || x >= GRID || z >= GRID) continue;
      this.ignite(z * GRID + x, 0.45 + this.rng() * 0.5);
    }
  }

  ignite(i: number, h: number) {
    if (this.state[i] !== TREE) return false;
    this.state[i] = FIRE; this.heat[i] = h; this.burning.push(i);
    return true;
  }

  private burnOut(i: number) {
    this.state[i] = BURNT; this.heat[i] = 0; this.burnt++; const hasCabin = this.cabins.some(c => c.cell === i);
    for (let k = 0; k < this.tCount[i]; k++) this.setTree(this.tStart[i] + k, true, hasCabin);
    this.mesh.instanceMatrix.needsUpdate = true; this.paintCell(i); const [x, z] = this.center(i);
    this.ev.onBurnt(x, z);
    for (const c of this.cabins) if (c.cell === i && !c.lost) {
      c.lost = true; c.mats[0].color.setRGB(0.05, 0.04, 0.035); c.mats[1].color.setRGB(0.03, 0.025, 0.02);
      this.ev.onCabinLost(x, z);
    }
  }

  private simStep(h: number) {
    const list = this.burning; this.burning = []; const w = this.wind;
    for (const i of list) {
      if (this.state[i] !== FIRE) continue;
      const k1 = this.kind[i] === 1 ? 1.6 : 1; this.heat[i] = Math.min(1, this.heat[i] + h * 0.2 * k1);
      this.fuel[i] -= h * (0.3 + this.heat[i]) * 0.1;
      if (this.fuel[i] <= 0) { this.burnOut(i); continue; }
      this.burning.push(i);
      if (this.heat[i] < 0.35) continue;
      const cx = i % GRID, cz = Math.floor(i / GRID);
      for (const [dx, dz, wt] of NB) {
        const x = cx + dx, z = cz + dz;
        if (x < 0 || z < 0 || x >= GRID || z >= GRID) continue;
        const j = z * GRID + x;
        if (this.state[j] !== TREE) continue;
        const align = (dx * w.x + dz * w.z) * wt; const wf = Math.max(0.1, 1 + w.str * 1.6 * align);
        const p = h * 0.045 * this.heat[i] * wf * wt * this.spreadMul * (this.kind[j] === 1 ? 1.8 : 1);
        if (this.rng() < p) this.ignite(j, 0.12);
      }
    }
    for (let i = 0; i < N; i++) {
      if (this.wet[i] <= 0) continue;
      this.wet[i] -= h;
      if (this.wet[i] <= 0 && this.state[i] === WET) { this.state[i] = TREE; this.paintCell(i); }
    }
  }

  /** Agua (o retardante) cayendo sobre (x, z). Devuelve cuánto fuego tocó y cuántas celdas apagó. */
  applyWater(x: number, z: number, r: number, amt: number, wetTime: number): { hiss: number; out: number } {
    let hiss = 0, out = 0;
    const i0 = Math.max(0, Math.floor((x - r + G_HALF) / CELL)), i1 = Math.min(GRID - 1, Math.floor((x + r + G_HALF) / CELL));
    const j0 = Math.max(0, Math.floor((z - r + G_HALF) / CELL)), j1 = Math.min(GRID - 1, Math.floor((z + r + G_HALF) / CELL));
    for (let j = j0; j <= j1; j++) for (let ii = i0; ii <= i1; ii++) {
      const i = j * GRID + ii; const [cx, cz] = this.center(i); const d = Math.hypot(cx - x, cz - z);
      if (d > r + CELL * 0.4) continue;
      const f = Math.min(1, 1.25 - d / (r + CELL * 0.4)); const st = this.state[i];
      if (st === FIRE) {
        hiss += this.heat[i]; this.heat[i] -= amt * f;
        if (this.heat[i] <= 0) { this.state[i] = WET; this.heat[i] = 0; this.wet[i] = wetTime; this.extinguished++; out++; this.paintCell(i); }
      } else if (st === TREE || st === WET) {
        this.wet[i] = Math.max(this.wet[i], wetTime * 0.7 * f);
        if (st === TREE) { this.state[i] = WET; this.paintCell(i); }
      }
    }
    return { hiss, out };
  }

  update(dt: number, t: number) {
    if (this.simulate) { this.acc += dt; while (this.acc >= 0.2) { this.acc -= 0.2; this.simStep(0.2); } }
    // Parpadeo de las copas en llamas
    for (const i of this.burning) {
      const hh = this.heat[i];
      for (let k = 0; k < this.tCount[i]; k++) {
        const tr = this.tStart[i] + k; this.baseColor(tr, i, _c);
        const fl = 0.75 + 0.25 * Math.sin(t * 14 + tr * 1.7) * Math.sin(t * 9.3 + tr);
        const m = Math.min(1, hh * 1.5);
        _c.setRGB(_c.r + (2.4 * fl - _c.r) * m, _c.g + (0.75 * fl - _c.g) * m, _c.b + (0.12 - _c.b) * m);
        this.mesh.setColorAt(tr, _c);
      }
    }
    if (this.burning.length && this.mesh.instanceColor) this.mesh.instanceColor.needsUpdate = true;
  }

  /** Pinta el minimapa (una celda = un píxel). */
  drawMap(img: ImageData, t: number) {
    const d = img.data;
    for (let i = 0; i < N; i++) {
      const st = this.state[i], o = i * 4; let r = 40, g = 52, b = 30;
      if (this.ground[i] < 0) { r = 30; g = 110; b = 150; }
      else if (st === TREE) { r = this.kind[i] ? 22 : 34; g = this.kind[i] ? 82 : 104; b = this.kind[i] ? 64 : 40; }
      else if (st === WET) { r = 40; g = 150; b = 150; }
      else if (st === FIRE) { const f = 0.7 + 0.3 * Math.sin(t * 10 + i); r = 255; g = Math.floor((90 + this.heat[i] * 120) * f); b = 20; }
      else if (st === BURNT) { r = 26; g = 22; b = 22; }
      d[o] = r; d[o + 1] = g; d[o + 2] = b; d[o + 3] = 255;
    }
  }

  dispose() {
    this.scene.remove(this.mesh); this.mesh.geometry.dispose(); (this.mesh.material as THREE.Material).dispose();
    for (const c of this.cabins) {
      this.scene.remove(c.group); c.group.traverse(o => { if (o instanceof THREE.Mesh) o.geometry.dispose(); });
      c.mats.forEach(m => m.dispose());
    }
  }
}

/** Estado de entrada unificado (teclado + controles táctiles). */
export interface InputState {
  turn: number;   // -1..1 (positivo = derecha)
  climb: number;  // -1..1 (positivo = subir)
  drop: boolean;  // soltar agua
  boost: boolean; // turbo
}

export class Input {
  state: InputState = { turn: 0, climb: 0, drop: false, boost: false };
  /** Valores fijados por el joystick y botones táctiles. */
  touch = { turn: 0, climb: 0, drop: false, boost: false }; onPause: (() => void) | null = null;
  onAnyKey: (() => void) | null = null; private keys = new Set<string>();

  private down = (e: KeyboardEvent) => {
    const k = e.code;
    if (['ArrowUp', 'ArrowDown', 'ArrowLeft', 'ArrowRight', 'Space'].includes(k)) e.preventDefault();
    this.onAnyKey?.();
    if ((k === 'Escape' || k === 'KeyP') && !e.repeat) { this.onPause?.(); return; }
    this.keys.add(k);
  };
  private up = (e: KeyboardEvent) => { this.keys.delete(e.code); }; private blur = () => { this.keys.clear(); };

  attach() {
    window.addEventListener('keydown', this.down); window.addEventListener('keyup', this.up);
    window.addEventListener('blur', this.blur);
  }
  detach() {
    window.removeEventListener('keydown', this.down); window.removeEventListener('keyup', this.up);
    window.removeEventListener('blur', this.blur);
  }

  /** Recalcula los ejes; una vez por fotograma. */
  update() {
    const k = this.keys, s = this.state, t = this.touch; let turn = t.turn, climb = t.climb;
    if (k.has('ArrowLeft') || k.has('KeyA')) turn -= 1;
    if (k.has('ArrowRight') || k.has('KeyD')) turn += 1;
    if (k.has('ArrowUp') || k.has('KeyW')) climb += 1;
    if (k.has('ArrowDown') || k.has('KeyS')) climb -= 1;
    s.turn = Math.max(-1, Math.min(1, turn)); s.climb = Math.max(-1, Math.min(1, climb));
    s.drop = k.has('Space') || k.has('KeyJ') || t.drop;
    s.boost = k.has('ShiftLeft') || k.has('ShiftRight') || k.has('KeyK') || t.boost;
  }

  reset() {
    this.keys.clear(); this.state = { turn: 0, climb: 0, drop: false, boost: false };
    this.touch.turn = 0; this.touch.climb = 0; this.touch.drop = false; this.touch.boost = false;
  }
}

/** Dificultades, configuración de niveles, tipos compartidos y récords. */
export type DiffId = 'facil' | 'normal' | 'experto';
export type Mode = 'menu' | 'play' | 'paused' | 'over';
export type MsgKind = 'big' | 'good' | 'warn' | 'info';

export interface Difficulty { label: string; sub: string; spread: number; wind: number; limit: number; dmg: number }
export const DIFFS: Record<DiffId, Difficulty> = {
  facil: { label: 'Novato', sub: 'Fuego lento y brisa suave', spread: 0.7, wind: 0.75, limit: 0.4, dmg: 0.6 },
  normal: { label: 'Piloto', sub: 'El reto equilibrado', spread: 1, wind: 1, limit: 0.3, dmg: 1 },
  experto: { label: 'Veterano', sub: 'Vendavales y focos rápidos', spread: 1.35, wind: 1.25, limit: 0.22, dmg: 1.3 },
};

export interface LevelCfg { name: string; clusters: number; size: number; spread: number; windStr: number; lightning: number; limit: number }
const NAMES = ['Valle Sereno', 'Pinar del Norte', 'Cañón Ventoso', 'Sierra Reseca', 'Tormenta Seca', 'Bosque Antiguo', 'Ola de Calor', 'Infierno Verde'];

export function levelConfig(level: number, diff: DiffId): LevelCfg {
  const d = DIFFS[diff];
  return {
    name: NAMES[(level - 1) % NAMES.length] + (level > NAMES.length ? ` ${Math.ceil(level / NAMES.length)}` : ''),
    clusters: Math.min(7, 1 + level),
    size: level >= 4 ? 2 : 1,
    spread: d.spread * (1 + 0.12 * (level - 1)),
    windStr: Math.min(1.7, (0.3 + level * 0.2) * d.wind),
    lightning: level >= 2 ? Math.max(9, 34 - level * 3) / d.spread : 0,
    limit: d.limit,
  };
}

export interface HudData {
  score: number; level: number; levelName: string; lives: number; tank: number; retard: number; hull: number; boost: number;
  alt: number; speed: number; fires: number; burntPct: number; limitPct: number; alive: number; windDeg: number; windKmh: number;
  combo: number; scooping: boolean; dropping: boolean; heatWarn: boolean; treeWarn: boolean; edgeWarn: boolean; hurt: number; flash: number;
}
export interface Summary {
  score: number; level: number; saved: number; extinguished: number; cabins: number; time: number;
  record: number; newRecord: boolean; diff: DiffId; reason: string;
}

const RECORD_KEY = 'bombero-aereo-records';
export function loadRecords(): Record<DiffId, number> {
  try {
    const r = JSON.parse(localStorage.getItem(RECORD_KEY) || '{}');
    return { facil: r.facil || 0, normal: r.normal || 0, experto: r.experto || 0 };
  } catch { return { facil: 0, normal: 0, experto: 0 }; }
}
export function saveRecord(diff: DiffId, score: number): boolean {
  const r = loadRecords();
  if (score <= r[diff]) return false;
  r[diff] = score;
  try { localStorage.setItem(RECORD_KEY, JSON.stringify(r)); } catch { /* sin almacenamiento */ }
  return true;
}

import * as THREE from 'three';

/** Tipos de partícula. Los 4 primeros van en el sistema aditivo; el resto en el normal. */
export const P = { FLAME: 0, GLOW: 1, EMBER: 2, SPARK: 3, SMOKE: 4, STEAM: 5, WATER: 6, SPRAY: 7, PINK: 8, DEBRIS: 9 } as const;

type RGB = [number, number, number];
// Rampas de color (inicio, medio, fin), alfa máxima, gravedad/flotación, rozamiento y empuje del viento
const SPEC: Array<{ c: [RGB, RGB, RGB]; a: number; g: number; drag: number; wind: number }> = [
  { c: [[1, 0.95, 0.7], [1, 0.48, 0.1], [0.55, 0.07, 0.02]], a: 0.95, g: 7, drag: 1.4, wind: 3 },     // FLAME
  { c: [[1, 0.55, 0.15], [0.9, 0.3, 0.06], [0.4, 0.08, 0.02]], a: 0.35, g: 0, drag: 2, wind: 0 },     // GLOW
  { c: [[1, 0.9, 0.5], [1, 0.5, 0.1], [0.8, 0.15, 0.02]], a: 1, g: 3, drag: 0.5, wind: 6 },           // EMBER
  { c: [[1, 1, 0.9], [0.7, 0.9, 1], [0.3, 0.6, 1]], a: 1, g: -6, drag: 1.5, wind: 0 },                // SPARK
  { c: [[0.35, 0.27, 0.22], [0.25, 0.22, 0.21], [0.42, 0.38, 0.36]], a: 0.6, g: 2.2, drag: 0.35, wind: 7 }, // SMOKE
  { c: [[0.95, 0.95, 0.95], [0.85, 0.86, 0.88], [0.75, 0.76, 0.8]], a: 0.55, g: 4, drag: 0.8, wind: 5 },    // STEAM
  { c: [[0.85, 0.95, 1], [0.6, 0.8, 0.95], [0.75, 0.88, 1]], a: 0.75, g: -26, drag: 0.35, wind: 2 },        // WATER
  { c: [[1, 1, 1], [0.85, 0.93, 1], [0.8, 0.9, 1]], a: 0.7, g: -14, drag: 1.2, wind: 2 },                   // SPRAY
  { c: [[1, 0.45, 0.7], [0.95, 0.3, 0.55], [0.9, 0.5, 0.7]], a: 0.8, g: -24, drag: 0.35, wind: 2 },         // PINK
  { c: [[0.2, 0.3, 0.1], [0.15, 0.2, 0.08], [0.1, 0.1, 0.06]], a: 1, g: -18, drag: 0.6, wind: 1 },          // DEBRIS
];

const VS = `
attribute vec3 aColor; attribute float aAlpha; attribute float aSize;
uniform float uScale; uniform float uNear; uniform float uFar;
varying vec3 vColor; varying float vAlpha; varying float vFog;
void main(){
  vec4 mv = modelViewMatrix * vec4(position, 1.0);
  gl_Position = projectionMatrix * mv;
  float d = -mv.z;
  gl_PointSize = aAlpha > 0.002 ? clamp(aSize * uScale / max(d, 1.0), 0.0, 900.0) : 0.0;
  vColor = aColor; vAlpha = aAlpha; vFog = smoothstep(uNear, uFar, d);
}`;
const FS = `
uniform sampler2D uTex; uniform vec3 uFog; uniform float uFogFade;
varying vec3 vColor; varying float vAlpha; varying float vFog;
void main(){
  vec4 t = texture2D(uTex, gl_PointCoord);
  vec3 c = mix(vColor * t.rgb, uFog, vFog);
  float a = t.a * vAlpha * (1.0 - vFog * uFogFade);
  if (a < 0.004) discard;
  gl_FragColor = vec4(c, a);
}`;

/** Textura de sprite: degradado radial (fuego) o nube algodonosa (humo/agua). */
export function makeSpriteTex(kind: 'fire' | 'puff'): THREE.CanvasTexture {
  const S = 64, cv = document.createElement('canvas'); cv.width = cv.height = S; const g = cv.getContext('2d')!;
  if (kind === 'fire') {
    const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
    gr.addColorStop(0, 'rgba(255,255,255,1)'); gr.addColorStop(0.25, 'rgba(255,255,255,0.75)');
    gr.addColorStop(0.6, 'rgba(255,255,255,0.18)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
    g.fillStyle = gr; g.fillRect(0, 0, S, S);
  } else {
    for (let k = 0; k < 9; k++) {
      const a = k * 2.4, r = k === 0 ? 0 : 9 + (k % 3) * 2;
      const x = 32 + Math.cos(a) * r, y = 32 + Math.sin(a) * r, rad = k === 0 ? 22 : 13 + (k % 2) * 3;
      const gr = g.createRadialGradient(x, y, 0, x, y, rad); const sh = 235 - (k % 3) * 18;
      gr.addColorStop(0, `rgba(${sh},${sh},${sh},0.55)`); gr.addColorStop(1, `rgba(${sh},${sh},${sh},0)`);
      g.fillStyle = gr; g.fillRect(0, 0, S, S);
    }
  }
  return new THREE.CanvasTexture(cv);
}

/** Sistema de partículas con un único THREE.Points y búfer circular. */
export class Particles {
  readonly points: THREE.Points; private geo = new THREE.BufferGeometry(); private mat: THREE.ShaderMaterial;
  private pos: Float32Array; private col: Float32Array; private alpha: Float32Array; private size: Float32Array;
  private vel: Float32Array; private life: Float32Array; private maxLife: Float32Array;
  private s0: Float32Array; private s1: Float32Array; private type: Uint8Array; private next = 0; count = 0;

  constructor(private scene: THREE.Scene, private max: number, additive: boolean, private tex: THREE.Texture, fog: THREE.Color) {
    this.pos = new Float32Array(max * 3); this.col = new Float32Array(max * 3);
    this.alpha = new Float32Array(max); this.size = new Float32Array(max);
    this.vel = new Float32Array(max * 3); this.life = new Float32Array(max); this.maxLife = new Float32Array(max);
    this.s0 = new Float32Array(max); this.s1 = new Float32Array(max); this.type = new Uint8Array(max);
    const dyn = (a: Float32Array, n: number) => { const b = new THREE.BufferAttribute(a, n); b.setUsage(THREE.DynamicDrawUsage); return b; };
    this.geo.setAttribute('position', dyn(this.pos, 3)); this.geo.setAttribute('aColor', dyn(this.col, 3));
    this.geo.setAttribute('aAlpha', dyn(this.alpha, 1)); this.geo.setAttribute('aSize', dyn(this.size, 1));
    this.mat = new THREE.ShaderMaterial({
      vertexShader: VS, fragmentShader: FS, transparent: true, depthWrite: false, fog: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
      uniforms: {
        uTex: { value: tex }, uScale: { value: 400 }, uNear: { value: 300 }, uFar: { value: 1500 },
        uFog: { value: additive ? new THREE.Color(0, 0, 0) : fog.clone() }, uFogFade: { value: additive ? 1 : 0.55 },
      },
    });
    this.points = new THREE.Points(this.geo, this.mat); this.points.frustumCulled = false;
    this.points.renderOrder = additive ? 3 : 2; scene.add(this.points);
  }

  setScale(px: number) { this.mat.uniforms.uScale.value = px; }

  emit(type: number, x: number, y: number, z: number, vx: number, vy: number, vz: number, life: number, s0: number, s1: number) {
    const i = this.next; this.next = (this.next + 1) % this.max; const o = i * 3;
    this.pos[o] = x; this.pos[o + 1] = y; this.pos[o + 2] = z;
    this.vel[o] = vx; this.vel[o + 1] = vy; this.vel[o + 2] = vz;
    this.life[i] = life; this.maxLife[i] = life; this.s0[i] = s0; this.s1[i] = s1; this.type[i] = type;
    this.alpha[i] = 0; this.size[i] = s0;
  }

  update(dt: number, wx: number, wz: number) {
    let n = 0;
    for (let i = 0; i < this.max; i++) {
      if (this.life[i] <= 0) { if (this.alpha[i] !== 0) this.alpha[i] = 0; continue; }
      n++; this.life[i] -= dt; const sp = SPEC[this.type[i]], o = i * 3;
      const t = 1 - Math.max(0, this.life[i]) / this.maxLife[i]; const dr = Math.max(0, 1 - sp.drag * dt);
      this.vel[o] = this.vel[o] * dr + wx * sp.wind * dt;
      this.vel[o + 1] = this.vel[o + 1] * (sp.g < 0 ? 1 : dr) + sp.g * dt;
      this.vel[o + 2] = this.vel[o + 2] * dr + wz * sp.wind * dt;
      this.pos[o] += this.vel[o] * dt; this.pos[o + 1] += this.vel[o + 1] * dt; this.pos[o + 2] += this.vel[o + 2] * dt;
      const c = sp.c, k = t < 0.5 ? t * 2 : (t - 0.5) * 2, A = t < 0.5 ? c[0] : c[1], B = t < 0.5 ? c[1] : c[2];
      this.col[o] = A[0] + (B[0] - A[0]) * k; this.col[o + 1] = A[1] + (B[1] - A[1]) * k; this.col[o + 2] = A[2] + (B[2] - A[2]) * k;
      const fadeIn = Math.min(1, t * (this.type[i] >= P.SMOKE ? 6 : 12));
      this.alpha[i] = sp.a * fadeIn * (1 - t) * (this.type[i] === P.SMOKE ? 1.35 - t * 0.35 : 1);
      this.size[i] = this.s0[i] + (this.s1[i] - this.s0[i]) * t;
      if (this.life[i] <= 0) this.alpha[i] = 0;
    }
    this.count = n;
    for (const k of ['position', 'aColor', 'aAlpha', 'aSize']) (this.geo.attributes[k] as THREE.BufferAttribute).needsUpdate = true;
  }

  clear() { this.life.fill(0); this.alpha.fill(0); (this.geo.attributes.aAlpha as THREE.BufferAttribute).needsUpdate = true; }

  dispose() { this.scene.remove(this.points); this.geo.dispose(); this.mat.dispose(); }
}

import * as THREE from 'three';
import { heightAt, WATER_Y, MAP_R } from './world';

export type PickKind = 'agua' | 'retardante' | 'reparar' | 'turbo';
export const PICK_INFO: Record<PickKind, { label: string; color: THREE.Color; css: string }> = {
  agua: { label: 'Depósito lleno', color: new THREE.Color(0.1, 0.5, 1), css: '#38bdf8' },
  retardante: { label: 'Retardante (más alcance)', color: new THREE.Color(1, 0.15, 0.5), css: '#f472b6' },
  reparar: { label: 'Reparación +45', color: new THREE.Color(0.15, 0.9, 0.3), css: '#4ade80' },
  turbo: { label: 'Turbo recargado', color: new THREE.Color(1, 0.75, 0.05), css: '#facc15' },
};
const ORDER: PickKind[] = ['agua', 'retardante', 'reparar', 'turbo', 'retardante', 'agua'];

interface Item { kind: PickKind; group: THREE.Group; core: THREE.Mesh; active: boolean; timer: number; base: number }

function glowTexture() {
  const cv = document.createElement('canvas'); cv.width = cv.height = 64; const g = cv.getContext('2d')!;
  const gr = g.createRadialGradient(32, 32, 0, 32, 32, 32);
  gr.addColorStop(0, 'rgba(255,255,255,0.9)'); gr.addColorStop(0.35, 'rgba(255,255,255,0.3)'); gr.addColorStop(1, 'rgba(255,255,255,0)');
  g.fillStyle = gr; g.fillRect(0, 0, 64, 64);
  return new THREE.CanvasTexture(cv);
}

/** Anillos de suministro flotantes que se recogen al atravesarlos. */
export class Pickups {
  items: Item[] = []; private tex = glowTexture(); private geos: THREE.BufferGeometry[] = [];
  private mats: THREE.Material[] = [];

  constructor(private scene: THREE.Scene) {
    const ring = new THREE.TorusGeometry(5.5, 0.55, 8, 32), core = new THREE.OctahedronGeometry(1.8);
    this.geos.push(ring, core);
    for (const kind of ORDER) {
      const c = PICK_INFO[kind].color; const mr = new THREE.MeshBasicMaterial({ color: c });
      const mc = new THREE.MeshBasicMaterial({ color: new THREE.Color(1, 1, 1).lerp(c, 0.4) });
      const sm = new THREE.SpriteMaterial({ map: this.tex, color: c, blending: THREE.AdditiveBlending, depthWrite: false, transparent: true });
      this.mats.push(mr, mc, sm); const group = new THREE.Group(); const coreMesh = new THREE.Mesh(core, mc);
      const glow = new THREE.Sprite(sm); glow.scale.setScalar(26);
      group.add(new THREE.Mesh(ring, mr), coreMesh, glow); scene.add(group);
      this.items.push({ kind, group, core: coreMesh, active: true, timer: 0, base: 40 });
    }
  }

  private place(it: Item, rnd: () => number, near?: THREE.Vector3) {
    const a = rnd() * Math.PI * 2, r = near ? 90 + rnd() * 120 : 120 + rnd() * (MAP_R - 200);
    const x = (near ? near.x : 0) + Math.cos(a) * r, z = (near ? near.z : 0) + Math.sin(a) * r;
    it.base = Math.max(heightAt(x, z), WATER_Y) + 30 + rnd() * 35; it.group.position.set(x, it.base, z);
    it.active = true; it.group.visible = true;
  }

  reset(rnd: () => number, start: THREE.Vector3) {
    this.items.forEach((it, i) => this.place(it, rnd, i === 0 ? start : undefined));
  }

  /** Anima, reaparece y comprueba si el avión atraviesa un anillo. */
  update(dt: number, t: number, plane: THREE.Vector3 | null): Item | null {
    let got: Item | null = null;
    for (const it of this.items) {
      if (!it.active) {
        it.timer -= dt;
        if (it.timer <= 0) this.place(it, Math.random);
        continue;
      }
      it.group.rotation.y += dt * 1.2; it.core.rotation.x += dt * 2;
      it.group.position.y = it.base + Math.sin(t * 1.5 + it.base) * 1.5;
      if (plane && plane.distanceTo(it.group.position) < 10) {
        it.active = false; it.group.visible = false; it.timer = 18; got = it;
      }
    }
    return got;
  }

  dispose() {
    this.items.forEach(it => this.scene.remove(it.group));
    this.geos.forEach(g => g.dispose()); this.mats.forEach(m => m.dispose()); this.tex.dispose();
  }
}

import * as THREE from 'three';
import { heightAt, WATER_Y } from './world';
import type { InputState } from './input';

const RED = new THREE.Color(0.55, 0.025, 0.018); const YELLOW = new THREE.Color(0.95, 0.56, 0.0);
const WHITE = new THREE.Color(0.82, 0.82, 0.8); const DARK = new THREE.Color(0.03, 0.03, 0.035);

export const BASE_SPEED = 46;
export const BOOST_SPEED = 74;

/** Hidroavión cisterna rojo y amarillo con física arcade. Avance local = +Z. */
export class Plane {
  group = new THREE.Group(); private model = new THREE.Group(); private props: THREE.Object3D[] = [];
  private beacon: THREE.Mesh; private geos: THREE.BufferGeometry[] = []; private mats: THREE.Material[] = [];
  pos = new THREE.Vector3(); yaw = 0; pitch = 0; roll = 0; speed = BASE_SPEED; vy = 0;
  tank = 100; hull = 100; boost = 100; overWater = false; scooping = false; boosting = false; groundHit = 0;

  constructor(private scene: THREE.Scene) {
    const mat = (c: THREE.Color, shin = 50, extra: Partial<THREE.MeshPhongMaterialParameters> = {}) => {
      const m = new THREE.MeshPhongMaterial({ color: c, shininess: shin, specular: new THREE.Color(0.25, 0.22, 0.2), ...extra });
      this.mats.push(m); return m;
    };
    const red = mat(RED), yellow = mat(YELLOW), white = mat(WHITE), dark = mat(DARK, 10);
    const glass = mat(new THREE.Color(0.04, 0.1, 0.16), 120, { specular: new THREE.Color(0.9, 0.9, 0.9) });
    const add = (g: THREE.BufferGeometry, m: THREE.Material, x: number, y: number, z: number, parent: THREE.Object3D = this.model) => {
      this.geos.push(g); const mesh = new THREE.Mesh(g, m); mesh.position.set(x, y, z); parent.add(mesh); return mesh;
    };
    const along = (g: THREE.BufferGeometry) => { g.rotateX(Math.PI / 2); return g; };

    add(along(new THREE.CylinderGeometry(1.05, 0.45, 10.5, 14)), red, 0, 0, 0);
    add(new THREE.SphereGeometry(1.05, 14, 10), red, 0, 0, 5.25).scale.set(1, 1, 1.35);
    add(new THREE.SphereGeometry(0.9, 12, 8), glass, 0, 0.72, 3.0).scale.set(0.95, 0.65, 1.6);
    add(new THREE.BoxGeometry(2.12, 0.34, 8.6), yellow, 0, -0.15, 0.2);
    add(new THREE.BoxGeometry(1.3, 0.12, 3), dark, 0, -1.02, 0.8);
    // Ala alta amarilla con puntas rojas
    add(new THREE.BoxGeometry(17, 0.32, 2.6), yellow, 0, 1.18, 1.3);
    add(new THREE.BoxGeometry(1.4, 0.36, 2.64), red, 8.2, 1.18, 1.3);
    add(new THREE.BoxGeometry(1.4, 0.36, 2.64), red, -8.2, 1.18, 1.3);
    add(new THREE.BoxGeometry(5, 0.34, 0.5), white, 0, 1.2, 0.2);
    // Motores y hélices
    for (const sx of [-3.7, 3.7]) {
      add(along(new THREE.CylinderGeometry(0.6, 0.5, 3.4, 12)), red, sx, 0.95, 2.3);
      add(new THREE.SphereGeometry(0.32, 8, 6), dark, sx, 0.95, 4.1);
      const prop = new THREE.Group(); prop.position.set(sx, 0.95, 4.15); this.model.add(prop);
      add(new THREE.BoxGeometry(0.28, 4.0, 0.08), dark, 0, 0, 0, prop);
      add(new THREE.BoxGeometry(4.0, 0.28, 0.08), dark, 0, 0, 0, prop);
      const discM = new THREE.MeshBasicMaterial({ color: new THREE.Color(0.6, 0.6, 0.6), transparent: true, opacity: 0.16, depthWrite: false, side: THREE.DoubleSide });
      this.mats.push(discM); add(new THREE.CircleGeometry(2.05, 20), discM, 0, 0, 0.05, prop); this.props.push(prop);
    }
    // Cola
    add(new THREE.BoxGeometry(0.26, 3.2, 2.3), red, 0, 1.8, -4.6);
    add(new THREE.BoxGeometry(0.28, 1.0, 2.32), yellow, 0, 3.0, -4.6);
    add(new THREE.BoxGeometry(6.4, 0.2, 1.7), yellow, 0, 0.55, -4.8);
    // Flotadores con montantes
    for (const sx of [-2.3, 2.3]) {
      add(along(new THREE.CylinderGeometry(0.5, 0.42, 7.6, 10)), white, sx, -2.7, 0.6);
      add(new THREE.SphereGeometry(0.5, 10, 6), red, sx, -2.7, 4.4).scale.set(1, 1, 1.8);
      add(new THREE.BoxGeometry(0.12, 0.2, 7.6), red, sx, -2.35, 0.6);
      add(new THREE.BoxGeometry(0.16, 2.2, 0.16), dark, sx * 0.72, -1.6, 2.4).rotation.z = sx > 0 ? 0.35 : -0.35;
      add(new THREE.BoxGeometry(0.16, 2.2, 0.16), dark, sx * 0.72, -1.6, -1.0).rotation.z = sx > 0 ? 0.35 : -0.35;
    }
    const bm = new THREE.MeshBasicMaterial({ color: new THREE.Color(1, 0.1, 0.05) }); this.mats.push(bm);
    this.beacon = add(new THREE.SphereGeometry(0.28, 8, 6), bm, 0, 3.6, -4.6); this.model.scale.setScalar(0.95);
    this.group.add(this.model); this.group.rotation.order = 'YXZ'; scene.add(this.group);
  }

  get forward() { return new THREE.Vector3(Math.sin(this.yaw), 0, Math.cos(this.yaw)); }

  reset(x: number, y: number, z: number, yaw: number) {
    this.pos.set(x, y, z); this.yaw = yaw; this.pitch = 0; this.roll = 0; this.vy = 0;
    this.speed = BASE_SPEED; this.tank = 100; this.hull = 100; this.boost = 100;
    this.group.visible = true; this.sync(0);
  }

  /** Avanza la física. Devuelve la altura del suelo bajo el avión. */
  update(dt: number, inp: InputState, wind: { x: number; z: number; str: number }, t: number): number {
    const turn = inp.turn, climb = inp.climb; this.roll += (turn * 0.8 - this.roll) * Math.min(1, dt * 3);
    this.yaw -= turn * 0.95 * dt; this.vy += (climb * 26 - this.vy) * Math.min(1, dt * 2.4);
    this.boosting = inp.boost && this.boost > 1;
    if (this.boosting) this.boost = Math.max(0, this.boost - dt * 28);
    else this.boost = Math.min(100, this.boost + dt * 7);
    const target = (this.boosting ? BOOST_SPEED : BASE_SPEED) - this.vy * 0.35 - this.tank * 0.05;
    this.speed += (target - this.speed) * Math.min(1, dt * 1.6); const f = this.forward;
    this.pos.x += (f.x * this.speed + wind.x * wind.str * 4) * dt;
    this.pos.z += (f.z * this.speed + wind.z * wind.str * 4) * dt; this.pos.y += this.vy * dt;
    const g = heightAt(this.pos.x, this.pos.z); this.overWater = g < WATER_Y - 0.4;
    const floor = this.overWater ? WATER_Y + 2.6 : g + 3.2; this.groundHit = 0;
    if (this.pos.y < floor) {
      if (!this.overWater) this.groundHit = Math.max(4, -this.vy);
      this.pos.y = floor; this.vy = Math.max(this.vy, this.overWater ? 0 : 6);
    }
    if (this.pos.y > 190) { this.pos.y = 190; this.vy = Math.min(this.vy, 0); }
    this.scooping = this.overWater && this.pos.y - WATER_Y < 5.5;
    if (this.scooping) this.tank = Math.min(100, this.tank + dt * 34);
    this.pitch = Math.atan2(this.vy, this.speed) * 0.9; this.sync(t);
    return g;
  }

  sync(t: number) {
    this.group.position.copy(this.pos); this.group.rotation.set(-this.pitch, this.yaw, this.roll);
    for (const p of this.props) p.rotation.z += 0.9;
    this.beacon.visible = Math.sin(t * 7) > 0.3; this.model.position.y = this.scooping ? Math.sin(t * 30) * 0.08 : 0;
  }

  /** Posición de la panza (de donde sale la cortina de agua). */
  belly(out: THREE.Vector3) {
    out.set(0, -1.4, 0.6).applyEuler(this.group.rotation).add(this.pos);
    return out;
  }

  dispose() {
    this.scene.remove(this.group); this.geos.forEach(g => g.dispose()); this.mats.forEach(m => m.dispose());
  }
}

import * as THREE from 'three';

/** Multiplica TODAS las intensidades de luz (r155+ usa unidades físicas). */
export const LIGHT_K = Number(THREE.REVISION) >= 155 ? Math.PI : 1;

export function setupRenderer(r: THREE.WebGLRenderer) {
  const a = r as any; const T = THREE as any;
  if ('outputColorSpace' in a) a.outputColorSpace = T.SRGBColorSpace; else a.outputEncoding = T.sRGBEncoding;
}

export function srgbTexture(t: THREE.Texture) {
  const a = t as any; const T = THREE as any;
  if ('colorSpace' in a) a.colorSpace = T.SRGBColorSpace; else a.encoding = T.sRGBEncoding;
  return t;
}

// r170 activa la gestión de color por defecto; r128 no la tiene. La apagamos para que
// los colores e iluminación coincidan en ambas versiones.
const CM = (THREE as any).ColorManagement;
if (CM && typeof CM.enabled === 'boolean') CM.enabled = false;

/** Convierte un color lineal a sRGB (para ShaderMaterial propios, que no codifican la salida). */
export function toSRGB(c: THREE.Color): THREE.Color {
  return new THREE.Color(Math.pow(c.r, 1 / 2.2), Math.pow(c.g, 1 / 2.2), Math.pow(c.b, 1 / 2.2));
}

import * as THREE from 'three';
import { LIGHT_K, toSRGB } from './three-compat';

/** Generador pseudoaleatorio con semilla (mulberry32). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return () => {
    a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function hash(x: number, y: number): number {
  let h = (x * 374761393 + y * 668265263) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177);
  return ((h ^ (h >>> 16)) >>> 0) / 4294967296;
}

/** Ruido de valor 2D suavizado, rango 0..1. */
export function vnoise(x: number, y: number): number {
  const xi = Math.floor(x), yi = Math.floor(y); const xf = x - xi, yf = y - yi;
  const u = xf * xf * (3 - 2 * xf), v = yf * yf * (3 - 2 * yf);
  const a = hash(xi, yi), b = hash(xi + 1, yi), c = hash(xi, yi + 1), d = hash(xi + 1, yi + 1);
  return a + (b - a) * u + (c - a) * v + (a - b - c + d) * u * v;
}

/** Ruido fractal (fBm), rango aproximado 0..1. */
export function fbm(x: number, y: number, oct = 4): number {
  let s = 0, amp = 0.5, f = 1, n = 0;
  for (let i = 0; i < oct; i++) { s += amp * vnoise(x * f, y * f); n += amp; amp *= 0.5; f *= 2.03; }
  return s / n;
}

export const smoothstep = (a: number, b: number, x: number) => {
  const t = Math.max(0, Math.min(1, (x - a) / (b - a)));
  return t * t * (3 - 2 * t);
};

/** Nivel del agua de los lagos y radio jugable del mapa. */
export const WATER_Y = 0;
export const MAP_R = 690;
export interface Lake { x: number; z: number; r: number }
export const LAKES: Lake[] = [
  { x: -380, z: 330, r: 175 },
  { x: 360, z: -300, r: 120 },
  { x: 300, z: 420, r: 80 },
  { x: -300, z: -380, r: 70 },
];

/** Altura del terreno: colinas suaves, cuencas de los lagos y montañas en el borde. */
export function heightAt(x: number, z: number): number {
  let h = 2 + fbm(x * 0.0042 + 11, z * 0.0042 - 7, 4) * 30; const edge = Math.max(0, Math.hypot(x, z) - 600) / 160;
  h += edge * edge * 70 + edge * fbm(x * 0.02, z * 0.02, 3) * 40;
  for (const l of LAKES) {
    const w = 1 + (fbm(x * 0.012 + l.x, z * 0.012, 2) - 0.5) * 0.45;
    const d = Math.hypot(x - l.x, z - l.z) / (l.r * w);
    if (d < 1.3) { const t = smoothstep(0.65, 1.3, d); h = -10 * (1 - t) + h * t; }
  }
  return h;
}
export const isWater = (x: number, z: number) => heightAt(x, z) < WATER_Y - 0.4;

/** Paleta del mundo (valores lineales; la salida los codifica a sRGB). */
export const FOG_LIN = new THREE.Color(0.46, 0.24, 0.12);
export const SUN_DIR = new THREE.Vector3(-0.5, 0.28, -0.82).normalize();

const SKY_VS = `varying vec3 vDir; void main(){ vDir = position; gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0); }`;
const SKY_FS = `
uniform vec3 uHorizon; uniform vec3 uZenith; uniform vec3 uLow; uniform vec3 uSun; uniform vec3 uSunDir; uniform float uFlash;
varying vec3 vDir;
void main(){
  vec3 d = normalize(vDir);
  float h = d.y;
  vec3 col = mix(uHorizon, uZenith, pow(smoothstep(0.0, 0.42, h), 0.7));
  col = mix(col, uLow, smoothstep(0.0, -0.25, h));
  float s = max(dot(d, uSunDir), 0.0);
  col += uSun * (pow(s, 6.0) * 0.35 + pow(s, 60.0) * 0.4 + smoothstep(0.9975, 0.999, s) * 1.2);
  float band = sin(d.x * 9.0 + d.z * 5.0) * 0.5 + 0.5;
  col = mix(col, uHorizon * 0.85, smoothstep(0.06, 0.0, abs(h - 0.08)) * band * 0.25);
  gl_FragColor = vec4(col + uFlash * vec3(0.6, 0.65, 0.8), 1.0);
}`;

const WATER_VS = `varying vec3 vW; void main(){ vec4 w = modelMatrix * vec4(position, 1.0); vW = w.xyz; gl_Position = projectionMatrix * viewMatrix * w; }`;
const WATER_FS = `
uniform float uTime; uniform vec3 uCam; uniform vec3 uSunDir; uniform vec3 uSky; uniform vec3 uDeep; uniform vec3 uFog; uniform vec3 uSun;
uniform float uNear; uniform float uFar; uniform vec3 uGlowPos; uniform float uGlow;
varying vec3 vW;
void main(){
  vec2 p = vW.xz;
  float a = p.x * 0.08 + uTime * 1.2, b = p.y * 0.06 - uTime * 0.9, c = (p.x + p.y) * 0.15 + uTime * 1.7, e = (p.x - p.y) * 0.31 - uTime * 2.6;
  vec3 n = normalize(vec3(cos(a) * 0.14 + cos(c) * 0.12 + cos(e) * 0.09, 1.0, cos(b) * 0.12 + cos(c) * 0.12 - cos(e) * 0.09));
  vec3 v = normalize(uCam - vW);
  float fr = pow(1.0 - max(dot(n, v), 0.0), 3.0);
  vec3 col = mix(uDeep, uSky, 0.28 + 0.7 * fr);
  vec3 r = reflect(-v, n);
  col += uSun * pow(max(dot(r, uSunDir), 0.0), 90.0) * 1.4;
  float gd = length(p - uGlowPos.xz);
  col += vec3(1.0, 0.42, 0.12) * uGlow * fr * exp(-gd / 240.0);
  float dist = length(uCam - vW);
  col = mix(col, uFog, smoothstep(uNear, uFar, dist));
  gl_FragColor = vec4(col, 1.0);
}`;

/** Cielo, terreno, lagos e iluminación. */
export class World {
  hemi: THREE.HemisphereLight; sun: THREE.DirectionalLight;
  private sky: THREE.Mesh; private skyMat: THREE.ShaderMaterial;
  private terrain: THREE.Mesh; private water: THREE.Mesh; private waterMat: THREE.ShaderMaterial;
  private baseCol: Float32Array; private colAttr: THREE.BufferAttribute; private posArr: Float32Array;
  private seg = 170; private size = 2100; private flash = 0;

  constructor(private scene: THREE.Scene) {
    scene.fog = new THREE.Fog(FOG_LIN.clone(), 280, 1450); const fogS = toSRGB(FOG_LIN);
    scene.background = fogS.clone();
    this.hemi = new THREE.HemisphereLight(new THREE.Color(0.95, 0.75, 0.62), new THREE.Color(0.16, 0.18, 0.1), 0.8 * LIGHT_K);
    this.sun = new THREE.DirectionalLight(new THREE.Color(1, 0.7, 0.42), 1.25 * LIGHT_K);
    this.sun.position.copy(SUN_DIR).multiplyScalar(600); scene.add(this.hemi, this.sun);

    this.skyMat = new THREE.ShaderMaterial({
      vertexShader: SKY_VS, fragmentShader: SKY_FS, side: THREE.BackSide, depthWrite: false, fog: false,
      uniforms: {
        uHorizon: { value: fogS.clone() }, uZenith: { value: new THREE.Color(0.13, 0.18, 0.36) },
        uLow: { value: fogS.clone().multiplyScalar(0.8) }, uSun: { value: new THREE.Color(1, 0.72, 0.42) },
        uSunDir: { value: SUN_DIR.clone() }, uFlash: { value: 0 },
      },
    });
    this.sky = new THREE.Mesh(new THREE.SphereGeometry(2600, 32, 16), this.skyMat);
    this.sky.renderOrder = -10; this.sky.frustumCulled = false; scene.add(this.sky);

    // Terreno con colores por vértice
    const g = new THREE.PlaneGeometry(this.size, this.size, this.seg, this.seg); g.rotateX(-Math.PI / 2);
    const pos = g.attributes.position as THREE.BufferAttribute; this.posArr = pos.array as Float32Array;
    const cols = new Float32Array(pos.count * 3);
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i), z = pos.getZ(i), h = heightAt(x, z); pos.setY(i, h);
      const n = fbm(x * 0.03, z * 0.03, 2); let r = 0.05 + n * 0.05, gg = 0.085 + n * 0.05, b = 0.03;
      if (h < 2.4) { const t = smoothstep(-2, 2.4, h); r = 0.3 * (1 - t) + r * t; gg = 0.22 * (1 - t) + gg * t; b = 0.1 * (1 - t) + b * t; }
      if (h > 38) { const t = smoothstep(38, 80, h); r += (0.17 - r) * t; gg += (0.15 - gg) * t; b += (0.13 - b) * t; }
      if (h > 120) { const t = smoothstep(120, 170, h); r += (0.7 - r) * t; gg += (0.66 - gg) * t; b += (0.62 - b) * t; }
      cols[i * 3] = r; cols[i * 3 + 1] = gg; cols[i * 3 + 2] = b;
    }
    this.baseCol = cols.slice(); this.colAttr = new THREE.BufferAttribute(cols, 3);
    g.setAttribute('color', this.colAttr); g.computeVertexNormals();
    this.terrain = new THREE.Mesh(g, new THREE.MeshLambertMaterial({ vertexColors: true })); scene.add(this.terrain);

    const sky = this.skyMat.uniforms;
    this.waterMat = new THREE.ShaderMaterial({
      vertexShader: WATER_VS, fragmentShader: WATER_FS, fog: false,
      uniforms: {
        uTime: { value: 0 }, uCam: { value: new THREE.Vector3() }, uSunDir: { value: SUN_DIR.clone() },
        uSky: { value: (sky.uHorizon.value as THREE.Color).clone() }, uDeep: { value: new THREE.Color(0.06, 0.2, 0.26) },
        uFog: { value: fogS.clone() }, uSun: { value: new THREE.Color(1, 0.75, 0.45) },
        uNear: { value: 280 }, uFar: { value: 1450 }, uGlowPos: { value: new THREE.Vector3() }, uGlow: { value: 0 },
      },
    });
    this.water = new THREE.Mesh(new THREE.PlaneGeometry(this.size, this.size, 1, 1), this.waterMat);
    this.water.rotation.x = -Math.PI / 2; this.water.position.y = WATER_Y; scene.add(this.water);
  }

  /** Ennegrece el suelo bajo una celda quemada. */
  scorch(x: number, z: number, r: number) {
    const step = this.size / this.seg, half = this.size / 2, row = this.seg + 1;
    const i0 = Math.max(0, Math.floor((x - r + half) / step)), i1 = Math.min(this.seg, Math.ceil((x + r + half) / step));
    const j0 = Math.max(0, Math.floor((z - r + half) / step)), j1 = Math.min(this.seg, Math.ceil((z + r + half) / step));
    const c = this.colAttr.array as Float32Array;
    for (let j = j0; j <= j1; j++) for (let i = i0; i <= i1; i++) {
      const k = j * row + i; const d = Math.hypot(this.posArr[k * 3] - x, this.posArr[k * 3 + 2] - z) / r;
      if (d > 1) continue;
      const f = 0.25 + d * 0.5; c[k * 3] = Math.min(c[k * 3], this.baseCol[k * 3] * f + 0.012);
      c[k * 3 + 1] = Math.min(c[k * 3 + 1], this.baseCol[k * 3 + 1] * f);
      c[k * 3 + 2] = Math.min(c[k * 3 + 2], this.baseCol[k * 3 + 2] * f);
    }
    this.colAttr.needsUpdate = true;
  }

  resetScorch() { (this.colAttr.array as Float32Array).set(this.baseCol); this.colAttr.needsUpdate = true; }

  lightning() { this.flash = 1; }

  update(dt: number, t: number, cam: THREE.Vector3, glowPos: THREE.Vector3 | null, glow: number) {
    this.sky.position.copy(cam); this.flash = Math.max(0, this.flash - dt * 4);
    const fl = this.flash * (0.6 + 0.4 * Math.sin(t * 60)); this.skyMat.uniforms.uFlash.value = fl;
    this.hemi.intensity = (0.8 + fl * 1.6) * LIGHT_K; const u = this.waterMat.uniforms;
    u.uTime.value = t; (u.uCam.value as THREE.Vector3).copy(cam);
    if (glowPos) (u.uGlowPos.value as THREE.Vector3).copy(glowPos);
    u.uGlow.value += (glow - u.uGlow.value) * Math.min(1, dt * 2);
  }

  dispose() {
    for (const m of [this.sky, this.terrain, this.water]) {
      this.scene.remove(m); m.geometry.dispose(); (m.material as THREE.Material).dispose();
    }
    this.scene.remove(this.hemi, this.sun);
  }
}
